sparql_query:
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department
WHERE {
  ?department rdf:type coresr-ont:Department .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?damage_property ?damage_value ?hazard ?hazard_type ?place_geometry ?startTime ?endTime
WHERE {
  BIND("2020-01-01T00:00:00Z"^^xsd:dateTime AS ?queryStartTime)
  BIND("2020-12-31T23:59:59Z"^^xsd:dateTime AS ?queryEndTime)

  ?damage_obs sosa:hasFeatureOfInterest ?hazard ;
              sosa:observedProperty ?damage_property ;
              sosa:hasSimpleResult ?damage_value .

  ?damage_property rdfs:subClassOf* kwg-ont:ImpactObservableProperty .
  FILTER(regex(str(?damage_property), "damage", "i"))

  ?hazard a ?hazard_type ;
          geo:hasGeometry ?place_geometry ;
          kwg-ont:hasTemporalScope ?temporal_entity .
  ?hazard_type rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  FILTER(regex(str(?hazard_type), "Storm|Tornado|Hurricane|Blizzard|Thunderstorm|Typhoon|Wind|Hail", "i"))

  OPTIONAL { ?temporal_entity time:inXSDDateTime ?instantTime . }
  OPTIONAL { ?temporal_entity time:hasBeginning/time:inXSDDateTime ?intervalStart . }
  OPTIONAL { ?temporal_entity time:hasEnd/time:inXSDDateTime ?intervalEnd . }

  BIND(COALESCE(?intervalStart, ?instantTime) AS ?startTime)
  BIND(COALESCE(?intervalEnd, ?instantTime) AS ?endTime)

  FILTER(?startTime <= ?queryEndTime && ?endTime >= ?queryStartTime)
}
ORDER BY ?startTime

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department ?missingFamilyNameCount
WHERE {
  {
    SELECT (MAX(?count) as ?maxCount)
    WHERE {
      SELECT (COUNT(?agent) as ?count)
      WHERE {
        ?department rdf:type coresr-ont:Department .
        ?department coresr-ont:hasAssociatedAgent ?agent .
        FILTER NOT EXISTS {
          ?agent coresr-ont:hasContactInformation ?contactInfo .
          ?contactInfo rdf:type coresr-ont:FamilyName .
        }
      }
      GROUP BY ?department
    }
  }
  {
    SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
    WHERE {
      ?department rdf:type coresr-ont:Department .
      ?department coresr-ont:hasAssociatedAgent ?agent .
      FILTER NOT EXISTS {
        ?agent coresr-ont:hasContactInformation ?contactInfo .
        ?contactInfo rdf:type coresr-ont:FamilyName .
      }
    }
    GROUP BY ?department
  }
  FILTER(?missingFamilyNameCount = ?maxCount)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publicationType (AVG(?publicationDate - ?submissionDate) AS ?avgDuration)
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasPublicationType ?publicationType ;
               coress-ont:dateOfSubmission ?submissionDate ;
               coress-ont:dateOfPublication ?publicationDate .
}
GROUP BY ?publicationType
ORDER BY DESC(?avgDuration)
LIMIT 1

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?agent ?department
WHERE {
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
  ?department a coresr-ont:Department .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?contactInfo .
    ?contactInfo a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?university ?publicationCount
WHERE {
  # Subquery to calculate the maximum publication count for each state
  {
    SELECT ?state (MAX(?count) as ?maxPublicationCount)
    WHERE {
      # Inner subquery to count publications for each university
      {
        SELECT ?state ?university (COUNT(DISTINCT ?publication) as ?count)
        WHERE {
          ?publication coress-ont:submittedBy ?author_role .
          ?agent coress-ont:performsRole ?author_role .
          ?author_role a coress-ont:Author .
          ?agent coress-ont:worksInDepartment ?department .
          ?department coress-ont:departmentOf ?college .
          ?college coress-ont:collegeOf ?university .
          ?university coress-ont:atState ?state .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  # Re-join with the individual university counts to find the one(s) that match the max
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) as ?publicationCount)
    WHERE {
      ?publication coress-ont:submittedBy ?author_role .
      ?agent coress-ont:performsRole ?author_role .
      ?author_role a coress-ont:Author .
      ?agent coress-ont:worksInDepartment ?department .
      ?department coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  # Filter to keep only the universities that have the maximum count for their state
  FILTER (?publicationCount = ?maxPublicationCount)
}
ORDER BY ?state

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publicationType (AVG(?daysDifference) AS ?avgTimeInDays)
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasPublicationType ?publicationType ;
               coress-ont:dateOfSubmission ?submissionDate ;
               coress-ont:dateOfPublication ?publicationDate .
  BIND(days-from-duration(?publicationDate - ?submissionDate) AS ?daysDifference)
}
GROUP BY ?publicationType
ORDER BY DESC(?avgTimeInDays)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attributeLabel)), "population") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "household") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "poverty") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "diabetic") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "obese")
  )
}
ORDER BY ?attribute

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?fieldOfStudy ?publicationTitle
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
  ?publication coresr-ont:hasTitle ?publicationTitle .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazardEvent ?name ?deaths ?cropDamage ?infraDamage ?affectedArea
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?university ?publicationCount
WHERE {
  {
    SELECT ?state (MAX(?count) AS ?maxCount)
    WHERE {
      {
        SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?count)
        WHERE {
          ?university a coresr-ont:University ;
                      coresr-ont:locatedAt ?location .
          ?location coresr-ont:atState ?state .
          ?college coresr-ont:partOf ?university .
          ?department coresr-ont:partOf ?college .
          ?agent coresr-ont:associatedWith ?department ;
                 coresr-ont:performsRole ?authorRole .
          ?authorRole a coresr-ont:Author .
          ?publication coresr-ont:submittedBy ?authorRole .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?publicationCount)
    WHERE {
      ?university a coresr-ont:University ;
                  coresr-ont:locatedAt ?location .
      ?location coresr-ont:atState ?state .
      ?college coresr-ont:partOf ?university .
      ?department coresr-ont:partOf ?college .
      ?agent coresr-ont:associatedWith ?department ;
             coresr-ont:performsRole ?authorRole .
      ?authorRole a coresr-ont:Author .
      ?publication coresr-ont:submittedBy ?authorRole .
    }
    GROUP BY ?state ?university
  }
  FILTER(?publicationCount = ?maxCount)
}
ORDER BY ?state

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?demographicAttribute
WHERE {
  ?collection a kwg-ont:CensusACS5YearEstimatesObservationCollection ;
              sosa:hasFeatureOfInterest ?place ;
              sosa:hasMember ?observation .
  ?observation sosa:observedProperty ?demographicAttribute .
  ?demographicAttribute a kwg-ont:CensusObservableProperty .
}
ORDER BY ?place ?demographicAttribute

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?damageToCrops ?damageToInfrastructure ?numberOfDeaths ?affectedArea
WHERE {
    ?hazard a kwgl-ont:HazardEvent .
    OPTIONAL {
        ?hazard kwgl-ont:damageToCropsInDollars ?damageToCrops .
    }
    OPTIONAL {
        ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure .
    }
    OPTIONAL {
        ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths .
    }
    OPTIONAL {
        ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea .
    }
    FILTER(BOUND(?damageToCrops) || BOUND(?damageToInfrastructure) || BOUND(?numberOfDeaths) || BOUND(?affectedArea))
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?climateAttribute
WHERE {
  ?climateAttribute rdfs:subClassOf kwg-ont:ClimateObservableProperty .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?state ?university ?pubCount
WHERE {
  {
    SELECT ?state (MAX(?count) AS ?maxPubCount)
    WHERE {
      {
        SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?count)
        WHERE {
          ?university rdf:type coresr-ont:University .
          ?university coresr-ont:locatedAt/coresr-ont:atState ?state .
          ?publication coresr-ont:hasContributor/coresr-ont:isPerformedBy/coresr-ont:associatedWith/coresr-ont:partOf/coresr-ont:partOf ?university .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?pubCount)
    WHERE {
      ?university rdf:type coresr-ont:University .
      ?university coresr-ont:locatedAt/coresr-ont:atState ?state .
      ?publication coresr-ont:hasContributor/coresr-ont:isPerformedBy/coresr-ont:associatedWith/coresr-ont:partOf/coresr-ont:partOf ?university .
    }
    GROUP BY ?state ?university
  }
  FILTER (?pubCount = ?maxPubCount)
}
ORDER BY ?state

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardAttribute ?damageDetail ?temporalData
WHERE {
    ?hurricane a kwg-ont:NOAAHurricane .
    {
        ?obsCollection sosa:hasFeatureOfInterest ?hurricane .
        FILTER NOT EXISTS { ?obsCollection a kwg-ont:ImpactObservationCollection . }
        ?obsCollection sosa:hasMember ?observation .
        ?observation sosa:observedProperty ?hazardAttribute .
    }
    UNION
    {
        ?obsCollection sosa:hasFeatureOfInterest ?hurricane ;
                       a kwg-ont:ImpactObservationCollection ;
                       sosa:hasMember ?observation .
        ?observation sosa:observedProperty ?damageDetail .
        OPTIONAL { ?obsCollection sosa:phenomenonTime ?temporalData . }
    }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?hazardName ?placeName ?startDate ?endDate ?cropDamage ?infraDamage ?deaths ?affectedArea
WHERE {
  VALUES ?stormType {
    kwglr:stormSurgeTide
    kwglr:strongWind
    kwglr:thunderstormWind
    kwglr:tornado
    kwglr:tropicalDepression
    kwglr:tropicalStorm
    kwglr:hurricane
    kwglr:iceStorm
    kwglr:winterStorm
    kwglr:blizzard
    kwglr:hail
    kwglr:heavyRain
  }

  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?stormType ;
          kwgl-ont:hasImpacted ?place ;
          kwgl-ont:hasStartDate ?startDate .

  FILTER (?startDate >= "2021-01-01"^^xsd:date && ?startDate <= "2021-12-31"^^xsd:date)

  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?publicationTypeString
WHERE {
  ?publication coresr-ont:hasPublicationType ?publicationType .
  ?publicationType coresr-ont:typeAsString ?publicationTypeString .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?placeName ?percentDiabetic ?percentObese
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName .
  OPTIONAL {
    ?place kwgl-ont:percentDiabetic ?percentDiabetic .
  }
  OPTIONAL {
    ?place kwgl-ont:percentObese ?percentObese .
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?state ?university ?pubCount
WHERE {
  {
    SELECT ?state (MAX(?count) AS ?maxPubCount)
    WHERE {
      SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?count)
      WHERE {
        ?university a coress-ont:University ;
                    coress-ont:atState ?state .
        ?college coress-ont:collegeOf ?university .
        ?department coress-ont:departmentOf ?college .
        ?agent coress-ont:worksInDepartment ?department .
        ?author coress-ont:isPerformedBy ?agent ;
                a coress-ont:Author .
        ?publication coress-ont:submittedBy ?author .
      }
      GROUP BY ?state ?university
    }
    GROUP BY ?state
  }
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?pubCount)
    WHERE {
      ?university a coress-ont:University ;
                  coress-ont:atState ?state .
      ?college coress-ont:collegeOf ?university .
      ?department coress-ont:departmentOf ?college .
      ?agent coress-ont:worksInDepartment ?department .
      ?author coress-ont:isPerformedBy ?agent ;
              a coress-ont:Author .
      ?publication coress-ont:submittedBy ?author .
    }
    GROUP BY ?state ?university
  }
  FILTER(?pubCount = ?maxPubCount)
}
ORDER BY ?state

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?climateAttribute
WHERE {
  ?climateAttribute rdfs:subClassOf kwg-ont:ClimateObservableProperty .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?publicationType
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?publicationType .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?floodHazard ?attribute ?detail
WHERE {
  VALUES ?floodType {
      kwg-ont:NOAAFlood
      kwg-ont:NOAAFlashFlood
      kwg-ont:NOAACoastalFlood
      kwg-ont:NOAALakeshoreFlood
  }
  ?floodHazard a ?floodType ;
               (kwg-ont:spatialRelation|kwg-ont:sfWithin) ?place .
  ?place a geo:Feature .

  {
    ?obsCollection sosa:hasFeatureOfInterest ?floodHazard ;
                   sosa:hasMember ?observation .
    ?observation sosa:observedProperty ?attribute ;
                 sosa:hasSimpleResult ?detail .
  }
  UNION
  {
    ?hazardEpisode kwg-ont:episodeHasPart ?floodHazard ;
                   kwg-ont:hasNarrative ?detail .
    BIND(kwg-ont:hasNarrative AS ?attribute)
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?firstName ?familyName ?field
WHERE {
  ?authorRole coress-ont:isPerformedBy ?agent ;
              coress-ont:advisedBy ?advisor ;
              coress-ont:submits ?publication .
  ?agent coress-ont:hasFirstName ?firstName ;
         coress-ont:hasFamilyName ?familyName .
  ?publication coress-ont:associatedFieldOfStudy ?field .
}
ORDER BY ?familyName ?firstName ?field

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?university ?pubCount
WHERE {
  {
    SELECT ?state (MAX(?count) as ?maxCount)
    WHERE {
      SELECT ?state ?university (COUNT(DISTINCT ?publication) as ?count)
      WHERE {
        ?publication coress-ont:submittedBy ?author .
        ?author coress-ont:isPerformedBy ?agent .
        ?agent coress-ont:worksInDepartment ?department .
        ?department coress-ont:departmentOf ?college .
        ?college coress-ont:collegeOf ?university .
        ?university coress-ont:atState ?state .
      }
      GROUP BY ?state ?university
    }
    GROUP BY ?state
  }
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) as ?pubCount)
    WHERE {
      ?publication coress-ont:submittedBy ?author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?department .
      ?department coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  FILTER(?pubCount = ?maxCount)
}
ORDER BY ?state

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?tornado_event ?place ?damage_type ?damage_value ?event_time
WHERE {
  ?tornado_event a kwg-ont:NOAATornado ;
                 kwg-ont:spatialRelation ?place .

  ?place a kwg-ont:AdministrativeRegion .

  ?impact_collection sosa:hasFeatureOfInterest ?tornado_event ;
                     a kwg-ont:ImpactObservationCollection ;
                     sosa:phenomenonTime ?temporal_entity ;
                     sosa:hasMember ?impact_observation .

  OPTIONAL { ?temporal_entity time:hasBeginning/time:inXSDDateTime ?begin_time . }
  OPTIONAL { ?temporal_entity time:inXSDDateTime ?instant_time . }
  BIND(COALESCE(?begin_time, ?instant_time) AS ?event_time)
  FILTER(?event_time >= "2020-01-01T00:00:00Z"^^xsd:dateTime && ?event_time < "2021-01-01T00:00:00Z"^^xsd:dateTime)

  ?impact_observation sosa:observedProperty ?damage_type ;
                      sosa:hasSimpleResult ?damage_value .

  FILTER (
    ?damage_type = kwgr:impactObservableProperty.damageCrop ||
    ?damage_type = kwgr:impactObservableProperty.damageProperty
  )
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazardEvent ?affectedArea ?damageToCrops ?damageToInfrastructure ?numberOfDeaths
WHERE {
  ?hazardEvent a ?type .
  ?type rdfs:subClassOf* kwgl-ont:HazardEvent .
  OPTIONAL {
    ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea .
  }
  OPTIONAL {
    ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops .
  }
  OPTIONAL {
    ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure .
  }
  OPTIONAL {
    ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?damageTypeLabel ?damageValue
WHERE {
  ?impactCollection a kwg-ont:ImpactObservationCollection ;
                    sosa:hasFeatureOfInterest ?hazard ;
                    sosa:hasMember ?observation .
  ?observation sosa:observedProperty ?damageType ;
               sosa:hasSimpleResult ?damageValue .
  ?damageType rdfs:label ?damageTypeLabel .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department ?missingFamilyNameCount
WHERE {
  {
    SELECT ?department (MAX(?count) as ?maxCount)
    WHERE {
      {
        SELECT ?department (COUNT(?agent) AS ?count)
        WHERE {
          ?department a coresr-ont:Department .
          ?department coresr-ont:hasAssociatedAgent ?agent .
          FILTER NOT EXISTS {
            ?agent coresr-ont:hasContactInformation ?contactInfo .
            ?contactInfo a coresr-ont:FamilyName .
          }
        }
        GROUP BY ?department
      }
    }
    GROUP BY ?department
  }
  {
    SELECT (MAX(?count) AS ?maxCountAll)
    WHERE {
      {
        SELECT (COUNT(?agent) AS ?count)
        WHERE {
          ?department a coresr-ont:Department .
          ?department coresr-ont:hasAssociatedAgent ?agent .
          FILTER NOT EXISTS {
            ?agent coresr-ont:hasContactInformation ?contactInfo .
            ?contactInfo a coresr-ont:FamilyName .
          }
        }
        GROUP BY ?department
      }
    }
  }
  BIND(?maxCount AS ?missingFamilyNameCount)
  FILTER(?maxCount = ?maxCountAll)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT (COUNT(?earthquakeHazard) AS ?numberOfEarthquakeHazards)
WHERE {
    ?earthquakeHazard a kwg-ont:Earthquake .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?city ?university ?college
WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:hasPart ?college ;
              coresr-ont:locatedAt ?location .
  ?college a coresr-ont:College .
  ?location coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
  ?city a coresr-ont:City .
}
ORDER BY ?city ?university ?college

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  ?attribute rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?fieldOfStudyLabel ?publicationTitle
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy ;
               coresr-ont:hasTitle ?publicationTitle .
  ?fieldOfStudy rdfs:label ?fieldOfStudyLabel .
}
ORDER BY ?fieldOfStudyLabel

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?placeName ?floodTypeLabel ?attributeLabel ?value ?narrative
WHERE {
  ?floodEvent a ?floodType .
  VALUES ?floodType {
    kwg-ont:NOAAFlood
    kwg-ont:NOAAFlashFlood
    kwg-ont:NOAACoastalFlood
    kwg-ont:NOAALakeshoreFlood
  }
  ?floodType rdfs:label ?floodTypeLabel .

  ?floodEvent kwg-ont:spatialRelation ?place .
  ?place a/rdfs:subClassOf* kwg-ont:AdministrativeRegion ;
         rdfs:label ?placeName .

  OPTIONAL {
    ?obsCollection sosa:hasFeatureOfInterest ?floodEvent ;
                   sosa:hasMember ?obs .
    ?obs sosa:observedProperty ?attribute ;
         sosa:hasSimpleResult ?value .
    ?attribute rdfs:label ?attributeLabel .
  }

  OPTIONAL {
    ?episode kwg-ont:episodeHasPart ?floodEvent ;
             kwg-ont:hasNarrative ?narrative .
  }
}
ORDER BY ?placeName

