PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazard ?property ?detail ?dateTime ?startTime ?endTime
WHERE {
  ?hazard a ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .

  ?hazard ?property ?detail .
  FILTER(?property != kwg-ont:hasTemporalScope)

  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temporalEntity .
    OPTIONAL {
      ?temporalEntity time:inXSDDateTime ?dateTime .
    }
    OPTIONAL {
      ?temporalEntity time:hasBeginning/time:inXSDDateTime ?startTime .
    }
    OPTIONAL {
      ?temporalEntity time:hasEnd/time:inXSDDateTime ?endTime .
    }
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?floodHazard ?attribute ?detail
WHERE {
  VALUES ?floodType {
    kwg-ont:NOAAFlood
    kwg-ont:NOAACoastalFlood
    kwg-ont:NOAAFlashFlood
    kwg-ont:NOAALakeshoreFlood
  }
  ?floodHazard a ?floodType .

  {
    BIND(?floodHazard AS ?place)
  }
  UNION
  {
    ?floodHazard kwg-ont:spatialRelation ?place .
  }

  {
    ?floodHazard ?attribute ?detail .
  }
  UNION
  {
    ?obsCollection sosa:hasFeatureOfInterest ?floodHazard .
    ?obsCollection sosa:hasMember ?observation .
    ?observation sosa:observedProperty ?attribute .
    ?attribute a ?detail .
    FILTER(?detail IN (kwg-ont:ImpactObservableProperty, kwg-ont:MagnitudeObservableProperty))
  }
}
ORDER BY ?place ?floodHazard ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?damageProperty ?propertyLabel ?domain ?range
WHERE {
  ?damageProperty rdf:type owl:DatatypeProperty .
  ?damageProperty rdfs:domain ?domain .

  VALUES ?domain { kwgl-ont:HazardEvent kwgl-ont:Place }

  OPTIONAL { ?damageProperty rdfs:label ?propertyLabel . }
  OPTIONAL { ?damageProperty rdfs:range ?range . }

  FILTER (
    CONTAINS(LCASE(STR(?damageProperty)), "damage") ||
    CONTAINS(LCASE(?propertyLabel), "damage")
  )
}
ORDER BY ?damageProperty

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?place ?storm_feature ?attribute ?value
WHERE {
  {
    ?obs_collection sosa:hasFeatureOfInterest ?storm_feature .
    ?storm_feature a kwg-ont:StormTrack .
    ?storm_feature kwg-ont:hasStormTracklet ?storm_tracklet .
    ?storm_tracklet kwg-ont:spatialRelation ?place .
    ?obs_collection sosa:hasMember ?observation .
    ?observation a kwg-ont:StormTrackObservation ;
                 sosa:observedProperty ?attribute ;
                 sosa:hasSimpleResult ?value .
  }
  UNION
  {
    ?obs_collection sosa:hasFeatureOfInterest ?storm_feature .
    ?storm_feature a kwg-ont:StormTracklet .
    ?storm_feature kwg-ont:spatialRelation ?place .
    ?obs_collection sosa:hasMember ?observation .
    ?observation a kwg-ont:StormTrackletObservation ;
                 sosa:observedProperty ?attribute ;
                 sosa:hasSimpleResult ?value .
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?agent ?department
WHERE {
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department ?missingFamilyNameCount
WHERE {
  {
    SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
    WHERE {
      ?department rdf:type coresr-ont:Department .
      ?department coresr-ont:hasAssociatedAgent ?agent .
      FILTER NOT EXISTS {
        ?agent coresr-ont:hasContactInformation ?contact .
        ?contact rdf:type coresr-ont:FamilyName .
      }
    }
    GROUP BY ?department
  }
  {
    SELECT (MAX(?count) as ?maxCount)
    WHERE {
      {
        SELECT (COUNT(?agent) AS ?count)
        WHERE {
          ?dept rdf:type coresr-ont:Department .
          ?dept coresr-ont:hasAssociatedAgent ?agent .
          FILTER NOT EXISTS {
            ?agent coresr-ont:hasContactInformation ?contact .
            ?contact rdf:type coresr-ont:FamilyName .
          }
        }
        GROUP BY ?dept
      }
    }
  }
  FILTER(?missingFamilyNameCount = ?maxCount)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?typeName (AVG(?timeDifferenceInDays) AS ?avgDuration)
WHERE {
    ?publication a coresr-ont:Publication ;
                 coresr-ont:dateOfSubmission ?submissionDate ;
                 coresr-ont:dateOfPublication ?publicationDate ;
                 coresr-ont:hasPublicationType ?pubType .
    ?pubType coresr-ont:typeAsString ?typeName .

    FILTER (?publicationDate > ?submissionDate)

    BIND(xsd:decimal(REPLACE(REPLACE(STR(?publicationDate - ?submissionDate), "P", ""), "D", "")) AS ?timeDifferenceInDays)
}
GROUP BY ?typeName
ORDER BY DESC(?avgDuration)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department ?missingFamilyNameCount
WHERE {
  {
    SELECT (MAX(?count) AS ?maxCount)
    WHERE {
      {
        SELECT (COUNT(?agent) AS ?count)
        WHERE {
          ?agent a coress-ont:Agent ;
                 coress-ont:worksInDepartment ?department .
          FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName . }
        }
        GROUP BY ?department
      }
    }
  }
  {
    SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
    WHERE {
      ?agent a coress-ont:Agent ;
             coress-ont:worksInDepartment ?department .
      FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName . }
    }
    GROUP BY ?department
  }
  FILTER(?missingFamilyNameCount = ?maxCount)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT (COUNT(DISTINCT ?attribute) AS ?earthquakeHazardCount)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  FILTER(
    CONTAINS(LCASE(STR(?attribute)), "earthquake") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "earthquake")
  )
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?publicationTypeLabel
WHERE {
  ?publication coresr-ont:hasPublicationType ?publicationType .
  ?publicationType coresr-ont:typeAsString ?publicationTypeLabel .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?place ?placeName ?population ?households ?poverty_rate ?diabetic_rate ?obese_rate
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?poverty_rate . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic_rate . }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese_rate . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?placeName ?hazardEvent ?hazardName ?numFloods ?floodDamage ?deaths ?cropDamage ?infraDamage ?startDate ?endDate
WHERE {
  ?hazardEvent kwgl-ont:hasHazardType kwglr:flood .
  ?place kwgl-ont:impactedBy ?hazardEvent ;
         kwgl-ont:hasName ?placeName .

  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?numFloods . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?floodDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?fieldOfStudy ?publicationTitle
WHERE {
  ?publication rdf:type coress-ont:Publication ;
               coress-ont:associatedFieldOfStudy ?fieldOfStudy ;
               coress-ont:hasTitle ?publicationTitle .
}
ORDER BY ?fieldOfStudy

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?attribute
WHERE {
  ?result a kwg-ont:ClimateDivisionObservationResult;
          sosa:hasFeatureOfInterest ?place;
          sosa:observedProperty ?attribute.
  ?place a/rdfs:subClassOf* geo:Feature.
  ?attribute a/rdfs:subClassOf* kwg-ont:ClimateObservableProperty.
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?uni ?pubCount
WHERE {
    {
        SELECT ?state (MAX(?pCount) AS ?maxPubCount)
        WHERE {
            {
                SELECT ?state ?uni (COUNT(DISTINCT ?pub) AS ?pCount)
                WHERE {
                    ?uni a coresr-ont:University ;
                         coresr-ont:locatedAt ?location .
                    ?location coresr-ont:atState ?state .
                    ?college coresr-ont:partOf ?uni .
                    ?dept coresr-ont:partOf ?college .
                    ?agent coresr-ont:associatedWith ?dept ;
                           coresr-ont:performsRole ?author .
                    ?author a coresr-ont:Author .
                    ?pub coresr-ont:submittedBy ?author .
                }
                GROUP BY ?state ?uni
            }
        }
        GROUP BY ?state
    }
    {
        SELECT ?state ?uni (COUNT(DISTINCT ?pub) AS ?pubCount)
        WHERE {
            ?uni a coresr-ont:University ;
                 coresr-ont:locatedAt ?location .
            ?location coresr-ont:atState ?state .
            ?college coresr-ont:partOf ?uni .
            ?dept coresr-ont:partOf ?college .
            ?agent coresr-ont:associatedWith ?dept ;
                   coresr-ont:performsRole ?author .
            ?author a coresr-ont:Author .
            ?pub coresr-ont:submittedBy ?author .
        }
        GROUP BY ?state ?uni
    }
    FILTER(?pubCount = ?maxPubCount)
}
ORDER BY ?state ?uni

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?damageProperty
  ?propertyLabel
  ?domain
  ?range
WHERE {
  ?damageProperty rdf:type owl:DatatypeProperty .
  OPTIONAL {
    ?damageProperty rdfs:label ?propertyLabel .
  }
  OPTIONAL {
    ?damageProperty rdfs:domain ?domain .
  }
  OPTIONAL {
    ?damageProperty rdfs:range ?range .
  }
  FILTER(CONTAINS(LCASE(STR(?damageProperty)), "damage") || CONTAINS(LCASE(?propertyLabel), "damage"))
}
ORDER BY ?damageProperty

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT
  ?place
  ?placeName
  ?population
  ?households
  ?povertyRate
  ?diabeticRate
  ?obeseRate
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyRate . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabeticRate . }
  OPTIONAL { ?place kwgl-ont:percentObese ?obeseRate . }
}
ORDER BY ?place

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hurricane ?hazardAttribute ?hazardAttributeValue ?damageImpactType ?damageImpactValue ?damageDateTime
WHERE {
  ?hurricane a kwg-ont:NOAAHurricane .

  {
    ?hurricane geo:hasGeometry ?hazardAttributeValue .
    BIND(geo:hasGeometry AS ?hazardAttribute)
  }
  UNION
  {
    ?hurricane kwg-ont:spatialRelation ?hazardAttributeValue .
    BIND(kwg-ont:spatialRelation AS ?hazardAttribute)
  }

  OPTIONAL {
    ?impact_obs a kwg-ont:ImpactObservation ;
                sosa:hasFeatureOfInterest ?hurricane ;
                sosa:observedProperty ?damageImpactType ;
                sosa:hasSimpleResult ?damageImpactValue .
    OPTIONAL {
      ?impact_obs sosa:phenomenonTime ?time_entity .
      ?time_entity time:inXSDDateTime ?damageDateTime .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX qudt: <http://qudt.org/1.1/schema/qudt#>

SELECT DISTINCT ?hurricane ?placeGeometry ?hazardAttributeLabel ?hazardValue ?damageTypeLabel ?damageValue ?damageBeginTime ?damageEndTime
WHERE {
  ?hurricane a kwg-ont:NOAAHurricane .

  OPTIONAL {
    ?hurricane kwg-ont:hasSegment/kwg-ont:startsFrom/geo:hasGeometry/geo:asWKT ?placeGeometry .
  }

  OPTIONAL {
    {
      ?magnitudeObsColl sosa:hasFeatureOfInterest ?hurricane ;
                        a kwg-ont:MagnitudeObservationCollection ;
                        sosa:hasMember ?magnitudeObs .
      ?magnitudeObs sosa:observedProperty ?hazardAttribute ;
                    sosa:hasSimpleResult ?hazardValue .
      ?hazardAttribute rdfs:label ?hazardAttributeLabel .
    } UNION {
      ?noaaHazard kwg-ont:hasPart ?hurricane ;
                  kwg-ont:hasStormTrack/kwg-ont:hasStormTracklet ?tracklet .
      ?trackletObsColl sosa:hasFeatureOfInterest ?tracklet ;
                       a kwg-ont:StormTrackletObservationCollection ;
                       sosa:hasMember ?trackletObs .
      ?trackletObs sosa:observedProperty ?hazardAttribute ;
                   sosa:hasSimpleResult ?hazardValue .
      ?hazardAttribute rdfs:label ?hazardAttributeLabel .
    }
  }

  OPTIONAL {
    ?impactObsColl sosa:hasFeatureOfInterest ?hurricane ;
                   a kwg-ont:ImpactObservationCollection ;
                   sosa:hasMember ?impactObs .
    ?impactObs sosa:observedProperty ?damageType ;
               sosa:hasSimpleResult ?damageValue .
    ?damageType rdfs:label ?damageTypeLabel .

    OPTIONAL {
      ?impactObsColl sosa:phenomenonTime ?temporalEntity .
      OPTIONAL { ?temporalEntity time:hasBeginning/time:inXSDDateTime ?begin . }
      OPTIONAL { ?temporalEntity time:hasEnd/time:inXSDDateTime ?damageEndTime . }
      OPTIONAL { ?temporalEntity time:inXSDDateTime ?instant . }
      BIND(COALESCE(?begin, ?instant) as ?damageBeginTime)
    }
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author;
          coresr-ont:advisedBy ?advisor.
  ?advisor a coresr-ont:Advisor.
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute (?totalCount AS ?numberOfTornadoAttributes)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?attr) AS ?totalCount)
    WHERE {
      ?attr rdf:type owl:DatatypeProperty .
      kwgl-ont:Place ?attr ?range .
      FILTER(CONTAINS(LCASE(STR(?attr)), "tornado"))
    }
  }
  ?attribute rdf:type owl:DatatypeProperty .
  kwgl-ont:Place ?attribute ?range .
  FILTER(CONTAINS(LCASE(STR(?attribute)), "tornado"))
}
ORDER BY ?attribute

