SELECT ?place ?placeName ?healthAttribute ?value
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName .
  {
    ?place kwgl-ont:percentDiabetic ?value .
    BIND(kwgl-ont:percentDiabetic AS ?healthAttribute)
  } UNION {
    ?place kwgl-ont:percentObese ?value .
    BIND(kwgl-ont:percentObese AS ?healthAttribute)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
