PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?hazardTypeLabel ?placeName ?attributeLabel ?value WHERE {

    ?obsCollection sosa:hasMember ?observation .
    ?observation sosa:observedProperty ?attribute ;
                 sosa:hasSimpleResult ?value .
    ?attribute rdfs:label ?attributeLabel .

    ?obsCollection sosa:hasFeatureOfInterest ?hazard .

    {
        ?hazard a kwg-ont:StormTracklet .
        ?obsCollection a kwg-ont:StormTrackletObservationCollection .
        ?hazard a ?hazardType.
        ?hazardType rdfs:label ?hazardTypeLabel.
    }
    UNION
    {
        VALUES ?hazardType {
            kwg-ont:NOAATornado kwg-ont:NOAAHurricane kwg-ont:NOAAWinterStorm
            kwg-ont:NOAABlizzard kwg-ont:NOAAIceStorm kwg-ont:NOAATropicalStorm
            kwg-ont:NOAAThunderstormWind
        }
        ?hazard a ?hazardType .
        ?hazardType rdfs:label ?hazardTypeLabel .

        ?obsCollection a ?obsType .
        FILTER(?obsType IN (kwg-ont:MagnitudeObservationCollection, kwg-ont:ImpactObservationCollection))
    }

    OPTIONAL {
        ?hazard kwg-ont:spatialRelation ?place .
        ?place a kwg-ont:AdministrativeRegion ;
               gnis:officialName ?placeName .
    }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardAttribute (COUNT(DISTINCT ?hazardAttribute) AS ?count)
WHERE {
  {
    SELECT DISTINCT ?hazardAttribute
    WHERE {
      {
        ?collection a kwg-ont:TornadoMagnitudeObservationCollection .
        ?collection sosa:hasMember ?observation .
        ?observation sosa:observedProperty ?hazardAttribute .
      }
      UNION
      {
        ?collection a kwg-ont:ImpactObservationCollection .
        ?collection sosa:hasFeatureOfInterest ?tornado .
        ?tornado a kwg-ont:NOAATornado .
        ?collection sosa:hasMember ?observation .
        ?observation sosa:observedProperty ?hazardAttribute .
      }
    }
  }
}
GROUP BY ?hazardAttribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?placeName ?stormEvent ?stormEventName ?hazardType ?affectedArea ?cropDamage ?infraDamage ?startDate ?endDate ?deaths
WHERE {
  ?place a kwgl-ont:Place;
         kwgl-ont:hasName ?placeName.
  ?stormEvent kwgl-ont:hasImpacted ?place;
              kwgl-ont:hasHazardType ?hazardType.
  VALUES ?hazardType {
    kwglr:blizzard
    kwglr:dustStorm
    kwglr:iceStorm
    kwglr:marineHighWind
    kwglr:marineStrongWind
    kwglr:marineThunderstormWind
    kwglr:marineTropicalDepression
    kwglr:marineTropicalStorm
    kwglr:stormSurgeTide
    kwglr:strongWind
    kwglr:thunderstormWind
    kwglr:tornado
    kwglr:tropicalDepression
    kwglr:tropicalStorm
    kwglr:winterStorm
    kwglr:hurricane
  }
  OPTIONAL { ?stormEvent kwgl-ont:hasName ?stormEventName . }
  OPTIONAL { ?stormEvent kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?stormEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?stormEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?stormEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?stormEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?stormEvent kwgl-ont:numberOfDeaths ?deaths . }
}

