WHERE {
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?typeName (AVG(?durationInDays) AS ?avgDurationInDays)
WHERE {
    ?publication a coresr-ont:Publication ;
                 coresr-ont:dateOfSubmission ?submissionDate ;
                 coresr-ont:dateOfPublication ?publicationDate ;
                 coresr-ont:hasPublicationType ?pubType .
    ?pubType coresr-ont:typeAsString ?typeName .

    BIND((?publicationDate - ?submissionDate) / xsd:dayTimeDuration("P1D") AS ?durationInDays)
    FILTER(?durationInDays >= 0)
}
GROUP BY ?typeName
ORDER BY DESC(?avgDurationInDays)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department ?missingCount
WHERE {
  {
    SELECT ?department (COUNT(?agent) AS ?missingCount)
    WHERE {
      ?agent a coresr-ont:Agent ;
             coresr-ont:associatedWith ?department .
      FILTER NOT EXISTS {
        ?agent coresr-ont:hasContactInformation ?contactInfo .
        ?contactInfo a coresr-ont:FamilyName .
      }
    }
    GROUP BY ?department
  }
  {
    SELECT (MAX(?c) as ?maxCount)
    WHERE {
      SELECT (COUNT(?agent) as ?c)
      WHERE {
        ?agent a coresr-ont:Agent ;
               coresr-ont:associatedWith ?someDepartment .
        FILTER NOT EXISTS {
          ?agent coresr-ont:hasContactInformation ?contactInfo .
          ?contactInfo a coresr-ont:FamilyName .
        }
      }
      GROUP BY ?someDepartment
    }
  }
  FILTER(?missingCount = ?maxCount)
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?place ?healthConcern WHERE {
  {
    # Health concerns modeled as observed properties (Public Health, Vulnerability, Impacts)
    ?obs sosa:hasFeatureOfInterest ?place ;
         sosa:observedProperty ?healthConcern .
    ?place a geo:Feature .
    {
      VALUES ?healthPropertyType {
          kwg-ont:PublicHealthObservableProperty
          kwg-ont:VulnerabilityObservableProperty
      }
      ?healthConcern rdfs:subClassOf* ?healthPropertyType .
    }
    UNION
    {
      VALUES ?healthConcern {
          kwgr:impactObservableProperty.deathDirect
          kwgr:impactObservableProperty.deathIndirect
          kwgr:impactObservableProperty.injuryDirect
          kwgr:impactObservableProperty.injuryIndirect
      }
    }
  }
  UNION
  {
    # Air Quality pollutants at measurement sites
    ?place a kwg-ont:AirQualitySite .
    ?collection sosa:madeBySensor/^sosa:hosts ?place .
    ?collection sosa:observedProperty ?healthConcern .
    ?healthConcern rdfs:subClassOf* kwg-ont:AirPollutant .
  }
  UNION
  {
    # Health-related attributes of Hospitals
    ?place a kwg-ont:Hospital .
    VALUES ?healthConcern {
        kwg-ont:hospitalType
        kwg-ont:noHospitalBeds
        kwg-ont:traumaCareLevel
        kwg-ont:hospitalStatus
        kwg-ont:helipadAvailability
    }
    ?place ?healthConcern [] .
  }
}

