PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earthquake_hazard ?detail_property ?detail_value
WHERE {
  ?earthquake_hazard a kwg-ont:Earthquake .
  ?observation sosa:hasFeatureOfInterest ?earthquake_hazard ;
               sosa:observedProperty ?detail_property ;
               sosa:hasSimpleResult ?detail_value .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiValue
WHERE {
  ?publication coresr-ont:hasIdentifier ?doi .
  ?doi coresr-ont:doiAsString ?doiValue .
