PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department ?missingFamilyNameCount
WHERE {
    {
        SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
        WHERE {
            ?agent a coress-ont:Agent ;
                   coress-ont:worksInDepartment ?department .
            FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName . }
        }
        GROUP BY ?department
    }
    FILTER NOT EXISTS {
        {
            SELECT (COUNT(?otherAgent) AS ?otherCount)
            WHERE {
                ?otherAgent a coress-ont:Agent ;
                            coress-ont:worksInDepartment ?otherDepartment .
                FILTER NOT EXISTS { ?otherAgent coress-ont:hasFamilyName ?familyName . }
            }
            GROUP BY ?otherDepartment
        }
        FILTER(?otherCount > ?missingFamilyNameCount)
    }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?typeAsString
WHERE {
  ?publication coresr-ont:hasPublicationType ?publicationType .
  ?publicationType coresr-ont:typeAsString ?typeAsString .
