PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardEvent ?impactProperty ?impactResult
WHERE {
  ?impactObservation a kwg-ont:ImpactObservation ;
    sosa:hasFeatureOfInterest ?hazardEvent ;
    sosa:observedProperty ?impactProperty ;
    sosa:hasSimpleResult ?impactResult .
  ?impactProperty rdfs:subClassOf* kwg-ont:ImpactObservableProperty .
  ?hazardEvent a/rdfs:subClassOf* kwg-ont:Hazard .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?hazardName ?place ?placeName ?hazardType ?startDate ?endDate ?deaths ?cropDamage ?infraDamage ?area
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?hazardType ;
          kwgl-ont:hasImpacted ?place ;
          kwgl-ont:hasStartDate ?startDate .

  FILTER(?hazardType IN (
    kwglr:hurricane,
    kwglr:tornado,
    kwglr:tropicalStorm,
    kwglr:winterStorm,
    kwglr:blizzard,
    kwglr:iceStorm,
    kwglr:stormSurgeTide,
    kwglr:thunderstormWind,
    kwglr:tropicalDepression
  ))

  FILTER(?startDate >= "2018-01-01"^^xsd:date && ?startDate <= "2022-12-31"^^xsd:date)

  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?hazardType ?damageType ?damageValue ?place ?startTime ?endTime
WHERE {
  ?impactObs a kwg-ont:ImpactObservation ;
             sosa:hasFeatureOfInterest ?hazard ;
             sosa:observedProperty ?damageType ;
             sosa:hasSimpleResult ?damageValue .

  ?hazard a ?hazardType .
  VALUES ?hazardType {
    kwg-ont:NOAATropicalStorm
    kwg-ont:NOAAHurricane
    kwg-ont:NOAAWinterStorm
    kwg-ont:NOAABlizzard
    kwg-ont:NOAAIceStorm
    kwg-ont:NOAAStormSurgeTide
    kwg-ont:NOAAMarineHurricaneTyphoon
    kwg-ont:NOAAMarineTropicalStorm
    kwg-ont:NOAATropicalDepression
    kwg-ont:NOAADustStorm
  }

  ?damageType rdfs:subClassOf* kwg-ont:ImpactObservableProperty .

  ?hazard kwg-ont:spatialRelation ?place ;
          kwg-ont:hasTemporalScope ?temporalEntity .

  OPTIONAL {
    ?temporalEntity time:hasBeginning/time:inXSDDateTime ?startTime .
  }
  OPTIONAL {
    ?temporalEntity time:hasEnd/time:inXSDDateTime ?endTime .
  }
}
ORDER BY ?hazard ?damageType

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?publication ?title
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasTitle ?title ;
               coress-ont:submittedBy ?authorRole .
  ?agent coress-ont:performsRole ?authorRole ;
         coress-ont:worksInDepartment ?department .
}
GROUP BY ?publication ?title
HAVING (COUNT(DISTINCT ?department) > 1)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?authorName ?field
WHERE {
  ?agent coresr-ont:performsRole ?authorRole ;
         coresr-ont:hasContactInformation ?nameInfo .
  ?authorRole rdf:type coresr-ont:Author ;
              coresr-ont:advisedBy ?advisorRole ;
              coresr-ont:submits ?publication .
  ?publication coresr-ont:associatedFieldOfStudy ?field .
  ?nameInfo rdf:type coresr-ont:Name ;
            coresr-ont:nameAsString ?authorName .
}
ORDER BY ?authorName ?field

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publicationTitle ?publicationTypeName
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasTitle ?publicationTitle ;
               coresr-ont:hasPublicationType ?publicationType .
  ?publicationType coresr-ont:typeAsString ?publicationTypeName .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?university ?publicationCount
WHERE {
  {
    SELECT ?state (MAX(?pCount) AS ?maxCount)
    WHERE {
      {
        SELECT ?state ?u (COUNT(DISTINCT ?p) AS ?pCount)
        WHERE {
          ?p coress-ont:submittedBy ?author .
          ?agent coress-ont:performsRole ?author ;
                 coress-ont:worksInDepartment ?department .
          ?department coress-ont:departmentOf ?college .
          ?college coress-ont:collegeOf ?u .
          ?u coress-ont:atState ?state .
        }
        GROUP BY ?state ?u
      }
    }
    GROUP BY ?state
  }
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?publicationCount)
    WHERE {
      ?publication coress-ont:submittedBy ?author .
      ?agent coress-ont:performsRole ?author ;
             coress-ont:worksInDepartment ?department .
      ?department coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  FILTER(?publicationCount = ?maxCount)
}
ORDER BY ?state

