  UNION
  {
    ?publication coresr-ont:hasContributor ?role .
  }
  ?role coresr-ont:isPerformedBy ?person .
  ?person coresr-ont:associatedWith ?department .
}
GROUP BY ?publication
HAVING (COUNT(DISTINCT ?department) > 1)

