WHERE {
  VALUES ?damageProperty { kwgr:impactObservableProperty.damageCrop kwgr:impactObservableProperty.damageProperty }
  ?collection sosa:hasFeatureOfInterest ?hazard ;
              sosa:hasMember ?observation .
  ?hazard a kwg-ont:NOAAHazardEvent .
  ?observation a kwg-ont:ImpactObservation ;
               sosa:observedProperty ?damageProperty ;
               sosa:hasSimpleResult ?damageValue .
  ?damageProperty rdfs:label ?damageType .
