PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?storm_feature ?attribute ?value ?geographical_place
WHERE {
  ?observation sosa:observedProperty ?attribute .
  {
    ?attribute rdfs:subClassOf* kwg-ont:StormTrackObservableProperty .
  }
  UNION
  {
    ?attribute rdfs:subClassOf* kwg-ont:StormTrackletObservableProperty .
  }
  ?observation sosa:hasSimpleResult ?value .
  ?obsCollection sosa:hasMember ?observation .
  ?obsCollection sosa:hasFeatureOfInterest ?storm_feature .
  ?storm_feature a geo:Feature .
  {
    BIND(?storm_feature AS ?geographical_place)
  }
  UNION
  {
    ?storm_feature kwg-ont:spatialRelation ?geographical_place .
  }
  UNION
  {
    ?storm_feature kwg-ont:hasStormTracklet/kwg-ont:spatialRelation ?geographical_place .
  }
}
ORDER BY ?storm_feature ?attribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

