PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "earthquake") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "earthquake")
  )
}
ORDER BY ?attribute

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?author ?publication ?field
WHERE {
  ?author rdf:type coresr-ont:Agent ;
          coresr-ont:performsRole ?authorRole .
  ?authorRole rdf:type coresr-ont:Author ;
              coresr-ont:advisedBy ?advisor ;
              coresr-ont:submits ?publication .
  ?publication coresr-ont:associatedFieldOfStudy ?field .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?storm_hazard ?attribute ?detail
WHERE {
    {
        ?storm_hazard a/rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
    }
    UNION
    {
        ?storm_hazard a kwg-ont:StormTrack .
    }
    UNION
    {
        ?storm_hazard a kwg-ont:StormTracklet .
    }

    ?storm_hazard kwg-ont:spatialRelation ?place .
    ?place a geo:Feature .

    {
        ?storm_hazard ?attribute ?detail .
        FILTER(isLiteral(?detail))
    }
    UNION
    {
        ?obsCollection sosa:hasFeatureOfInterest ?storm_hazard ;
                       sosa:hasMember ?observation .
        ?observation sosa:observedProperty ?attribute ;
                     sosa:hasSimpleResult ?detail .
    }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department ?missingCount
WHERE {
  {
    SELECT ?department (COUNT(?agent) AS ?missingCount)
    WHERE {
      ?agent a coress-ont:Agent ;
             coress-ont:worksInDepartment ?department .
      FILTER NOT EXISTS {
        ?agent coress-ont:hasFamilyName ?familyName .
      }
    }
    GROUP BY ?department
  }
  {
    SELECT (MAX(?c) AS ?maxCount)
    WHERE {
      {
        SELECT (COUNT(?agent) AS ?c)
        WHERE {
          ?agent a coress-ont:Agent ;
                 coress-ont:worksInDepartment ?department .
          FILTER NOT EXISTS {
            ?agent coress-ont:hasFamilyName ?familyName .
          }
        }
        GROUP BY ?department
      }
    }
  }
  FILTER (?missingCount = ?maxCount)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?earthquake ?hazardType ?name ?startDate ?endDate ?deaths ?damageToCrops ?damageToInfrastructure ?affectedArea
WHERE {
  ?earthquake rdf:type kwgl-ont:Earthquake .
  ?earthquake kwgl-ont:hasHazardType ?hazardType .
  OPTIONAL { ?earthquake kwgl-ont:hasName ?name . }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?state ?university ?publicationCount WHERE {
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?publicationCount)
    WHERE {
      ?university a coress-ont:University ;
                  coress-ont:atState ?state .
      ?university coress-ont:hasCollege/coress-ont:hasDepartment/coress-ont:hasAgent/coress-ont:performsRole ?author .
      ?author a coress-ont:Author ;
              coress-ont:submits ?publication .
    }
    GROUP BY ?state ?university
  }
  {
    SELECT ?state (MAX(?p_count) AS ?maxCount)
    WHERE {
      {
        SELECT ?state (COUNT(DISTINCT ?publication) AS ?p_count)
        WHERE {
          ?university a coress-ont:University ;
                      coress-ont:atState ?state .
          ?university coress-ont:hasCollege/coress-ont:hasDepartment/coress-ont:hasAgent/coress-ont:performsRole ?author .
          ?author a coress-ont:Author ;
                  coress-ont:submits ?publication .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  FILTER(?publicationCount = ?maxCount)
}
ORDER BY ASC(?state)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?state ?university ?publicationCount
WHERE {
  # Subquery to calculate the publication count for each university
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?publicationCount)
    WHERE {
      ?university rdf:type coress-ont:University ;
                  coress-ont:atState ?state ;
                  coress-ont:hasCollege ?college .
      ?college coress-ont:hasDepartment ?department .
      ?agent coress-ont:worksInDepartment ?department .
      ?agent coress-ont:performsRole ?authorRole .
      ?authorRole coress-ont:submits ?publication .
    }
    GROUP BY ?state ?university
  }
  # Subquery to determine the maximum publication count within each state
  {
    SELECT ?state (MAX(?pCount) AS ?maxPublicationCount)
    WHERE {
      {
        SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?pCount)
        WHERE {
          ?university rdf:type coress-ont:University ;
                      coress-ont:atState ?state ;
                      coress-ont:hasCollege ?college .
          ?college coress-ont:hasDepartment ?department .
          ?agent coress-ont:worksInDepartment ?department .
          ?agent coress-ont:performsRole ?authorRole .
          ?authorRole coress-ont:submits ?publication .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  # Filter to select only those universities whose publication count matches the maximum for their state
  FILTER(?publicationCount = ?maxPublicationCount)
}
ORDER BY ?state

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?attribute ?totalCount
WHERE {
  {
    SELECT DISTINCT ?attribute
    WHERE {
      ?tornado a kwg-ont:NOAATornado .
      ?obsCollection sosa:hasFeatureOfInterest ?tornado .
      ?obsCollection sosa:hasMember ?observation .
      ?observation sosa:observedProperty ?attribute .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?attr) AS ?totalCount)
    WHERE {
      ?tornado a kwg-ont:NOAATornado .
      ?obsCollection sosa:hasFeatureOfInterest ?tornado .
      ?obsCollection sosa:hasMember ?observation .
      ?observation sosa:observedProperty ?attr .
    }
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?agent ?department
WHERE {
    ?agent a coress-ont:Agent ;
           coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?university ?publicationCount
WHERE {
  {
    SELECT ?state (MAX(?count) AS ?maxCount)
    WHERE {
      SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?count)
      WHERE {
        ?college coress-ont:collegeOf ?university .
        ?department coress-ont:departmentOf ?college .
        ?agent coress-ont:worksInDepartment ?department .
        ?agent coress-ont:performsRole ?authorRole .
        ?publication coress-ont:submittedBy ?authorRole .
        ?authorRole a coress-ont:Author .
        ?university coress-ont:atState ?state .
      }
      GROUP BY ?state ?university
    }
    GROUP BY ?state
  }
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?publicationCount)
    WHERE {
      ?college coress-ont:collegeOf ?university .
      ?department coress-ont:departmentOf ?college .
      ?agent coress-ont:worksInDepartment ?department .
      ?agent coress-ont:performsRole ?authorRole .
      ?publication coress-ont:submittedBy ?authorRole .
      ?authorRole a coress-ont:Author .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  FILTER(?publicationCount = ?maxCount)
}
ORDER BY ?state

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publicationTypeName (AVG(?publicationDate - ?submissionDate) AS ?avgProcessingTime)
WHERE {
  ?publication coresr-ont:hasPublicationType ?publicationType ;
               coresr-ont:dateOfSubmission ?submissionDate ;
               coresr-ont:dateOfPublication ?publicationDate .
  ?publicationType coresr-ont:typeAsString ?publicationTypeName .
}
GROUP BY ?publicationTypeName
ORDER BY DESC(?avgProcessingTime)
LIMIT 1

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

