PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?tornadoAttribute ?totalCount
WHERE {
  {
    SELECT DISTINCT ?tornadoAttribute WHERE {
      { ?tornadoAttribute a kwg-ont:ImpactObservableProperty . }
      UNION
      { ?tornadoAttribute a kwg-ont:MagnitudeObservableProperty . }
    }
  }
  {
    SELECT (COUNT(DISTINCT ?attr) AS ?totalCount) WHERE {
      { ?attr a kwg-ont:ImpactObservableProperty . }
      UNION
      { ?attr a kwg-ont:MagnitudeObservableProperty . }
    }
  }
}
ORDER BY ?tornadoAttribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?earthquake ?detailProperty ?detailValue
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  ?observation sosa:hasFeatureOfInterest ?earthquake .
  ?observation sosa:observedProperty ?detailProperty ;
               sosa:hasSimpleResult ?detailValue .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?earthquakeHazard (COUNT(?earthquakeHazard) as ?numberOfEarthquakeHazards)
