  {
    SELECT DISTINCT ?earthquakeHazard
    WHERE {
      ?earthquakeHazard rdf:type kwgl-ont:Earthquake .
    }
  }
}
GROUP BY ?earthquakeHazard

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?earthquake ?name ?hazardType ?startDate ?endDate ?deaths ?damageToInfrastructure ?damageToCrops ?affectedArea
