SELECT ?city ?university ?college
WHERE {
  ?university rdf:type coresr-ont:University ;
              coresr-ont:locatedAt ?location ;
              coresr-ont:hasPart ?college .
  ?location coresr-ont:atState ?state .
  ?city rdf:type coresr-ont:City ;
        coresr-ont:hasState ?state .
  ?college rdf:type coresr-ont:College .
}
ORDER BY ?city ?university ?college

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department ?missingCount
WHERE {
  {
    SELECT ?department (COUNT(?agent) AS ?missingCount)
    WHERE {
      ?agent coress-ont:worksInDepartment ?department .
      FILTER NOT EXISTS {
        ?agent coress-ont:hasFamilyName ?familyName .
      }
    }
    GROUP BY ?department
  }
  {
    SELECT (MAX(?c) as ?maxCount)
    WHERE {
      {
        SELECT (COUNT(?agent) AS ?c)
        WHERE {
          ?agent coress-ont:worksInDepartment ?department .
          FILTER NOT EXISTS {
            ?agent coress-ont:hasFamilyName ?familyName .
          }
        }
        GROUP BY ?department
      }
    }
  }
  FILTER(?missingCount = ?maxCount)
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
