SELECT ?publication ?title
WHERE {
  ?publication rdf:type coresr-ont:Publication ;
               coresr-ont:hasTitle ?title ;
               coresr-ont:hasContributor ?contributor .
  ?contributor coresr-ont:isPerformedBy ?person .
  ?person coresr-ont:associatedWith ?department .
}
GROUP BY ?publication ?title
HAVING (COUNT(DISTINCT ?department) > 1)

