PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?authorName ?advisor
WHERE {
  ?authorRole rdf:type coress-ont:Author ;
              coress-ont:isPerformedBy ?authorAgent ;
              coress-ont:advisedBy ?advisor .
  ?authorAgent coress-ont:hasFirstName ?firstName ;
               coress-ont:hasFamilyName ?familyName .
  BIND(CONCAT(?firstName, " ", ?familyName) AS ?authorName)
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  ?impactCollection a kwg-ont:ImpactObservationCollection ;
                    sosa:hasFeatureOfInterest ?hazardEvent ;
                    sosa:hasMember ?impactObservation .
  ?impactObservation sosa:observedProperty ?impactProperty ;
                     sosa:hasSimpleResult ?impactValue .
}
ORDER BY ?hazardEvent ?impactProperty

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT (GROUP_CONCAT(DISTINCT ?attribute; separator=" | ") AS ?tornadoAttributes) (COUNT(DISTINCT ?attribute) AS ?attributeCount)
WHERE {
  ?tornado a kwg-ont:NOAATornado .
  ?observation sosa:hasFeatureOfInterest ?tornado .
  ?observation sosa:observedProperty ?attribute .
  {
    ?observation a kwg-ont:MagnitudeObservation .
  }
  UNION
  {
    ?observation a kwg-ont:ImpactObservation .
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?publicationTypeName
WHERE {
  ?publication coresr-ont:hasPublicationType ?publicationType .
  ?publicationType coresr-ont:typeAsString ?publicationTypeName .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publicationTitle ?publicationType
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasTitle ?publicationTitle ;
               coresr-ont:hasPublicationType ?type .
  ?type coresr-ont:typeAsString ?publicationType .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?hazardName ?hazardType ?place ?placeName ?startDate ?endDate ?damageToCrops ?damageToInfrastructure ?numberOfDeaths ?affectedArea
WHERE {
  VALUES ?hazardType {
    kwglr:blizzard
    kwglr:hurricane
    kwglr:iceStorm
    kwglr:stormSurgeTide
    kwglr:thunderstormWind
    kwglr:tornado
    kwglr:tropicalDepression
    kwglr:tropicalStorm
    kwglr:winterStorm
  }
  ?hazardEvent kwgl-ont:hasHazardType ?hazardType ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:hasStartDate ?startDate .
  FILTER (?startDate >= "2019-01-01"^^xsd:date && ?startDate <= "2019-12-31"^^xsd:date)
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?publicationType
WHERE {
  ?publication rdf:type coress-ont:Publication ;
               coress-ont:hasPublicationType ?publicationType .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazard ?property ?value ?timeValue
WHERE {
  ?hazard a ?hazardType .
  ?hazardType rdfs:subClassOf* kwg-ont:Hazard .
  ?hazard ?property ?value .

  OPTIONAL {
    {
      ?hazard kwg-ont:hasTemporalScope ?temporalEntity .
    }
    UNION
    {
      ?observation sosa:hasFeatureOfInterest ?hazard ;
                   sosa:phenomenonTime ?temporalEntity .
    }
    OPTIONAL { ?temporalEntity time:inXSDDateTime ?t1 . }
    OPTIONAL { ?temporalEntity time:hasBeginning/time:inXSDDateTime ?t2 . }
    BIND(COALESCE(?t1, ?t2) AS ?timeValue)
    FILTER(BOUND(?timeValue))
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?detailProperty ?detailValue ?time
WHERE {
  ?hazard a/rdfs:subClassOf* kwg-ont:Hazard .
  ?hazard ?detailProperty ?detailValue .
  OPTIONAL {
    { ?hazard kwg-ont:hasTemporalScope ?temp . ?temp time:inXSDDateTime ?t1 . }
    UNION
    { ?hazard kwg-ont:hasTemporalScope ?temp . ?temp time:hasBeginning [ time:inXSDDateTime ?t1 ] . }
    UNION
    { ?obs sosa:hasFeatureOfInterest ?hazard ; sosa:phenomenonTime ?temp . ?temp time:inXSDDateTime ?t1 . }
    UNION
    { ?obs sosa:hasFeatureOfInterest ?hazard ; sosa:phenomenonTime ?temp . ?temp time:hasBeginning [ time:inXSDDateTime ?t1 ] . }
    UNION
    { ?hazard kwg-ont:hasDeclaration [ kwg-ont:hasDeclarationDate [ time:inXSDDateTime ?t1 ] ] . }
  }
  BIND(COALESCE(?t1) AS ?time)
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT (COUNT(DISTINCT ?hazard) AS ?numberOfEarthquakeHazards)
WHERE {
  {
    ?hazard rdf:type kwgl-ont:Earthquake .
  }
  UNION
  {
    ?event kwgl-ont:hasHazardType kwglr:earthquake .
    ?hazard rdf:type ?event .
  }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?demographicAttribute
WHERE {
  ?obsCollection sosa:hasFeatureOfInterest ?place .
  ?obsCollection sosa:hasMember ?observation .
  ?observation sosa:observedProperty ?demographicAttribute .

  {
    ?obsCollection a kwg-ont:CensusACS5YearEstimatesObservationCollection .
    ?demographicAttribute a kwg-ont:CensusObservableProperty .
  }
  UNION
  {
    ?obsCollection a kwg-ont:PublicHealthObservationCollection .
    ?demographicAttribute a kwg-ont:PublicHealthObservableProperty .
  }
}
ORDER BY ?place ?demographicAttribute

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?hazardName ?deaths ?infraDamageDollars ?cropDamageDollars ?affectedAcres
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamageDollars . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamageDollars . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedAcres . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?hazard
  ?hazardName
  ?placeName
  ?hazardTypeLabel
  ?startDate
  ?endDate
  ?damageToCrops
  ?damageToInfrastructure
  ?numberOfDeaths
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?hazardType ;
          kwgl-ont:hasImpacted ?place ;
          kwgl-ont:hasStartDate ?startDate .

  ?hazardType rdfs:label ?hazardTypeLabel .

  FILTER (
    CONTAINS(LCASE(?hazardTypeLabel), "storm") ||
    CONTAINS(LCASE(?hazardTypeLabel), "hurricane") ||
    CONTAINS(LCASE(?hazardTypeLabel), "tornado") ||
    CONTAINS(LCASE(?hazardTypeLabel), "blizzard")
  )

  FILTER (?startDate >= "2020-01-01"^^xsd:date && ?startDate <= "2022-12-31"^^xsd:date)

  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths . }

  FILTER (BOUND(?damageToCrops) || BOUND(?damageToInfrastructure) || BOUND(?numberOfDeaths))
}
ORDER BY DESC(?startDate)

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?damageType ?damageValue
WHERE {
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazard ;
                     sosa:observedProperty ?damageType ;
                     sosa:hasSimpleResult ?damageValue .
  ?hazard a kwg-ont:Hazard .
  ?damageType rdfs:subClassOf* kwg-ont:ImpactObservableProperty .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?place ?storm_feature ?attribute ?value
WHERE {
  ?storm_tracklet a kwg-ont:StormTracklet ;
                  kwg-ont:spatialRelation ?place .

  {
    BIND(?storm_tracklet AS ?storm_feature)
    ?observation a kwg-ont:StormTrackletObservation ;
                 sosa:hasFeatureOfInterest ?storm_feature .
  }
  UNION
  {
    ?storm_track kwg-ont:hasStormTracklet ?storm_tracklet .
    BIND(?storm_track AS ?storm_feature)
    ?observation a kwg-ont:StormTrackObservation ;
                 sosa:hasFeatureOfInterest ?storm_feature .
  }

  ?observation sosa:observedProperty ?attribute ;
               sosa:hasSimpleResult ?value .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?author ?field ?publication
WHERE {
  ?authorRole rdf:type coresr-ont:Author ;
              coresr-ont:isPerformedBy ?author ;
              coresr-ont:advisedBy ?advisor ;
              coresr-ont:submits ?publication .
  ?publication coresr-ont:associatedFieldOfStudy ?field .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazardEvent ?name ?hazardType ?deaths ?affectedArea ?cropDamage ?infraDamage ?startDate ?endDate ?impactedPlace
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasImpacted ?impactedPlace . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?property ?value ?time
WHERE {
  ?hazard a/rdfs:subClassOf* kwg-ont:Hazard .
  ?hazard ?property ?value .
  OPTIONAL {
    { ?hazard kwg-ont:hasTemporalScope ?temporalEntity . }
    UNION
    {
      ?obsCollection sosa:hasFeatureOfInterest ?hazard ;
                     sosa:phenomenonTime ?temporalEntity .
    }
    ?temporalEntity (time:inXSDDateTime | time:hasBeginning/time:inXSDDateTime) ?time .
  }
}
ORDER BY ?hazard

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hurricane ?hazardAttribute ?place ?damageDetail ?damageTime
WHERE {
  {
    SELECT ?hurricane ?hazardAttribute ?place
    WHERE {
      ?hurricane a kwg-ont:NOAAHurricane .
      ?hurricane geo:hasGeometry ?place .
      ?observation sosa:hasFeatureOfInterest ?hurricane .
      ?observation a kwg-ont:MagnitudeObservation .
      ?observation sosa:observedProperty ?hazardAttribute .
    }
  }
  UNION
  {
    SELECT ?hurricane ?place ?damageDetail ?damageTime
    WHERE {
      ?hurricane a kwg-ont:NOAAHurricane .
      ?hurricane geo:hasGeometry ?place .
      ?impactObservation sosa:hasFeatureOfInterest ?hurricane .
      ?impactObservation a kwg-ont:ImpactObservation .
      ?impactObservation sosa:observedProperty ?damageDetail .
      OPTIONAL {
        ?impactObservation sosa:phenomenonTime ?temporalEntity .
        ?temporalEntity time:inXSDDateTime ?damageTime .
      }
    }
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?attribute
WHERE {
  {
    # Find properties directly associated with climate divisions
    ?attribute rdfs:domain kwg-ont:USClimateDivision .
    FILTER(CONTAINS(LCASE(STR(?attribute)), "climate"))
  }
  UNION
  {
    # Find all specific climate observable properties (e.g., avg temp, precipitation)
    ?attribute a kwg-ont:ClimateObservableProperty .
  }
  UNION
  {
    # Find properties of climate observation results (e.g., anomaly, rank)
    ?attribute rdfs:domain kwg-ont:ClimateDivisionObservationResult .
  }
}
ORDER BY ?attribute

