PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?tornadoHazard ?damageProperty ?damageValue ?geometryWKT ?beginTime ?endTime
WHERE {
  ?tornadoHazard a kwg-ont:NOAATornado .
  ?impactObservation sosa:hasFeatureOfInterest ?tornadoHazard ;
                     sosa:observedProperty ?damageProperty ;
                     sosa:hasSimpleResult ?damageValue .
  VALUES ?damageProperty {
    kwgr:impactObservableProperty.damageProperty
    kwgr:impactObservableProperty.damageCrop
  }
  ?tornadoHazard geo:hasGeometry/geo:asWKT ?geometryWKT .
  ?tornadoHazard kwg-ont:hasTemporalScope ?temporalEntity .
  OPTIONAL {
    ?temporalEntity time:hasBeginning/time:inXSDDateTime ?startTime .
  }
  OPTIONAL {
    ?temporalEntity time:hasEnd/time:inXSDDateTime ?endTime .
  }
  OPTIONAL {
    ?temporalEntity time:inXSDDateTime ?instantTime .
  }
  BIND(COALESCE(?startTime, ?instantTime) AS ?beginTime)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?pubType (AVG(?publicationDate - ?submissionDate) AS ?avgDuration)
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasPublicationType ?pubType ;
               coress-ont:dateOfSubmission ?submissionDate ;
               coress-ont:dateOfPublication ?publicationDate .
  FILTER(?publicationDate > ?submissionDate)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDuration)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdfs:domain kwgl-ont:Place ;
             rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?earthquake ?details ?hazardTypeLabel ?eventType ?magnitude ?depth
WHERE {
    ?earthquake a kwg-ont:Earthquake .
    kwg-ont:Earthquake rdfs:label ?hazardTypeLabel .
    FILTER(LANG(?hazardTypeLabel) = "" || LANGMATCHES(LANG(?hazardTypeLabel), "en"))

    OPTIONAL { ?earthquake kwg-ont:detailsURL ?details . }

    OPTIONAL {
        SELECT ?earthquake (SAMPLE(?type) AS ?eventType) (SAMPLE(?mag) AS ?magnitude) (SAMPLE(?dep) AS ?depth)
        WHERE {
            ?obsCollection sosa:hasFeatureOfInterest ?earthquake ;
                           sosa:hasMember ?obs .
            ?obs sosa:observedProperty ?prop ;
                 sosa:hasSimpleResult ?value .

            BIND(IF(?prop = kwgr:earthquakeObservableProperty.type, ?value, UNDEF) AS ?type)
            BIND(IF(?prop = kwgr:earthquakeObservableProperty.mag, ?value, UNDEF) AS ?mag)
            BIND(IF(?prop = kwgr:earthquakeObservableProperty.depth, ?value, UNDEF) AS ?dep)
        }
        GROUP BY ?earthquake
    }
}

