PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?tornado ?damageDetailType ?damageDetailValue ?place ?startTime ?endTime
WHERE {
  ?tornado a kwg-ont:NOAATornado ;
           kwg-ont:spatialRelation ?place .
  ?place a kwg-ont:AdministrativeRegion .

  ?obsCollection sosa:hasFeatureOfInterest ?tornado ;
                 sosa:hasMember ?obs ;
                 sosa:phenomenonTime ?timeInterval .

  ?obs sosa:observedProperty ?damageDetailType ;
       sosa:hasSimpleResult ?damageDetailValue .

  FILTER (
    (?obsCollection a kwg-ont:ImpactObservationCollection && 
     ?damageDetailType IN (kwgr:impactObservableProperty.damageCrop, kwgr:impactObservableProperty.damageProperty))
    ||
    (?obsCollection a kwg-ont:TornadoMagnitudeObservationCollection && 
     ?damageDetailType = kwgr:magnitudeObservableProperty.fujitaScale)
  )

  OPTIONAL { ?timeInterval time:hasBeginning/time:inXSDDateTime ?startTimeValue . }
  OPTIONAL { ?timeInterval time:hasEnd/time:inXSDDateTime ?endTimeValue . }
  OPTIONAL { ?timeInterval a time:Instant; time:inXSDDateTime ?instantTime . }

  BIND(COALESCE(?startTimeValue, ?instantTime) AS ?startTime)
  BIND(COALESCE(?endTimeValue, ?instantTime) AS ?endTime)
}
ORDER BY ?tornado ?place ?startTime

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?author
WHERE {
  ?author a coress-ont:Author .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?place ?attribute ?value ?startDate ?endDate
WHERE {
  ?hurricane a kwgl-ont:Hurricane ;
             kwgl-ont:hasImpacted ?place .
  OPTIONAL {
    ?hurricane kwgl-ont:hasStartDate ?startDate .
  }
  OPTIONAL {
    ?hurricane kwgl-ont:hasEndDate ?endDate .
  }
  {
    ?hurricane ?attribute ?value .
    FILTER(?attribute != rdf:type && ?attribute != kwgl-ont:hasImpacted)
  }
  UNION
  {
    {
      ?attribute rdfs:subPropertyOf* kwgl-ont:dollarDamageOfHurricanesImpactingPlace .
    }
    UNION
    {
      ?attribute rdfs:subPropertyOf* kwgl-ont:numberOfHurricanesImpactingPlace .
    }
    ?place ?attribute ?value .
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?agent ?department
WHERE {
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publicationTitle ?publicationType
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasTitle ?publicationTitle ;
               coress-ont:hasPublicationType ?publicationType .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication
WHERE {
  {
    ?publication coresr-ont:submittedBy ?role .
  }
  UNION
  {
    ?publication coresr-ont:hasContributor ?role .
  }
  ?role coresr-ont:isPerformedBy ?agent .
  ?agent coresr-ont:associatedWith ?department .
}
GROUP BY ?publication
HAVING(COUNT(DISTINCT ?department) > 1)

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>

SELECT DISTINCT ?place ?placeLabel ?healthAttribute ?attributeLabel ?value
WHERE {
  VALUES ?obsType {
    kwg-ont:PublicHealthObservation
    kwg-ont:VulnerabilityObservation
    kwg-ont:AirQualityObservation
  }
  ?obs a ?obsType .
  ?obs sosa:hasFeatureOfInterest ?place .
  ?obs sosa:observedProperty ?healthAttribute .

  OPTIONAL { ?obs sosa:hasSimpleResult ?val1 . }
  OPTIONAL { ?obs kwg-ont:dailyAQIValue ?val2 . }
  BIND(COALESCE(?val1, ?val2) AS ?value)
  FILTER(BOUND(?value))

  OPTIONAL { ?healthAttribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?place kwg-ont:siteName|gnis:officialName|rdfs:label ?placeLabel . }
}
ORDER BY ?placeLabel ?attributeLabel

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?publicationTitle ?publicationTypeString
WHERE {
  ?publication coresr-ont:hasPublicationType ?publicationType ;
               coresr-ont:hasTitle ?publicationTitle .
  ?publicationType coresr-ont:typeAsString ?publicationTypeString .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?hazardName ?cropDamage ?infrastructureDamage ?numberOfDeaths
WHERE {
  ?hazard rdf:type/rdfs:subClassOf* kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  FILTER (BOUND(?cropDamage) || BOUND(?infrastructureDamage) || BOUND(?numberOfDeaths))
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?publication
WHERE {
    ?agent coresr-ont:associatedWith ?department .
    ?agent coresr-ont:performsRole ?role .
    { ?publication coresr-ont:submittedBy ?role . }
    UNION
    { ?role coresr-ont:contributedTo ?publication . }
}
GROUP BY ?publication
HAVING (COUNT(DISTINCT ?department) > 1)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
