PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?floodHazard ?hazardType ?geographicalPlace ?attribute ?value
WHERE {
  VALUES ?hazardType {
    kwg-ont:NOAAFlood
    kwg-ont:NOAAFlashFlood
    kwg-ont:NOAACoastalFlood
    kwg-ont:NOAALakeshoreFlood
    kwg-ont:NOAAStormSurgeTide
  }
  ?floodHazard a ?hazardType .
  ?floodHazard ?attribute ?value .
  OPTIONAL {
    ?floodHazard kwg-ont:spatialRelation ?geographicalPlace .
  }
}
ORDER BY ?floodHazard ?attribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  ?impactObs a kwg-ont:ImpactObservation ;
             sosa:hasFeatureOfInterest ?hazardEvent ;
             sosa:observedProperty ?impactProperty ;
             sosa:hasSimpleResult ?impactValue .
  ?impactProperty rdfs:subClassOf* kwg-ont:ImpactObservableProperty .
  ?hazardEvent a/rdfs:subClassOf* kwg-ont:Hazard .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?authorName ?advisorName
WHERE {
  ?authorRole a coress-ont:Author ;
              coress-ont:isPerformedBy ?agent ;
              coress-ont:advisedBy ?advisorName .

  ?agent coress-ont:hasFirstName ?firstName ;
         coress-ont:hasFamilyName ?lastName .

  BIND(CONCAT(?firstName, " ", ?lastName) AS ?authorName)
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardEvent ?impactPropertyLabel ?impactValue
WHERE {
  ?impactObsCollection sosa:hasFeatureOfInterest ?hazardEvent ;
                     a kwg-ont:ImpactObservationCollection ;
                     sosa:hasMember ?impactObservation .
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
  ?impactObservation sosa:observedProperty ?impactProperty ;
                     sosa:hasSimpleResult ?impactValue .
  ?impactProperty rdfs:label ?impactPropertyLabel .
}
ORDER BY ?hazardEvent ?impactPropertyLabel

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?climateAttribute
WHERE {
  ?obsCollection a kwg-ont:ClimateDivisionObservationCollection ;
                 sosa:hasFeatureOfInterest ?place ;
                 sosa:hasMember ?propObsCollection .
  ?propObsCollection sosa:observedProperty ?climateAttribute .
}
ORDER BY ?place

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?hazard ?label ?name ?narrative ?timeValue
WHERE {
  {
    ?hazard kwg-ont:hasTemporalScope/(time:inXSDDateTime|time:inXSDDate|time:inXSDgYear|time:inXSDDateTimeStamp) ?timeValue .
  } UNION {
    ?obs sosa:hasFeatureOfInterest ?hazard ;
         sosa:phenomenonTime/(time:inXSDDateTime|time:inXSDDate|time:inXSDgYear|time:inXSDDateTimeStamp) ?timeValue .
  } UNION {
    ?hazard kwg-ont:hasDeclaration/kwg-ont:hasDeclarationDate ?timeValue .
    FILTER(isLiteral(?timeValue))
  } UNION {
    ?hazard kwg-ont:hasDeclaration/kwg-ont:hasDeclarationDate/(time:inXSDDateTime|time:inXSDDate|time:inXSDgYear|time:inXSDDateTimeStamp) ?timeValue .
  }

  ?hazard a kwg-ont:Hazard .

  OPTIONAL { ?hazard rdfs:label ?label . }
  OPTIONAL {
    { ?hazard kwg-ont:hasDisasterName ?name . }
    UNION { ?hazard kwg-ont:hasFireName ?name . }
    UNION { ?hazard kwg-ont:hasIncidentName ?name . }
  }
  OPTIONAL {
    ?episode kwg-ont:episodeHasPart ?hazard .
    ?episode kwg-ont:hasNarrative ?narrative .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?hazard ?hazardTypeLabel ?details ?narrative ?startTime ?endTime ?instantTime
WHERE {
  ?hazard a ?hazardType .
  ?hazardType rdfs:subClassOf* kwg-ont:Hazard .

  OPTIONAL { ?hazardType rdfs:label ?hazardTypeLabel . }
  OPTIONAL { ?hazard rdfs:label|gnis:officialName|kwg-ont:hasDisasterName|kwg-ont:hasFireName|kwg-ont:hasIncidentName ?details . }
  OPTIONAL { 
    ?episode kwg-ont:episodeHasPart ?hazard . 
    ?episode kwg-ont:hasNarrative ?narrative . 
  }

  OPTIONAL {
    {
      ?hazard kwg-ont:hasTemporalScope ?tempEntity .
      OPTIONAL { ?tempEntity time:hasBeginning/(time:inXSDDateTime|time:inXSDDate) ?startTime . }
      OPTIONAL { ?tempEntity time:hasEnd/(time:inXSDDateTime|time:inXSDDate) ?endTime . }
      OPTIONAL { ?tempEntity (time:inXSDDateTime|time:inXSDDate) ?instantTime . }
    }
    UNION
    {
      ?obsCollection sosa:hasFeatureOfInterest ?hazard ;
                     sosa:phenomenonTime ?tempEntity .
      OPTIONAL { ?tempEntity time:hasBeginning/(time:inXSDDateTime|time:inXSDDate) ?startTime . }
      OPTIONAL { ?tempEntity time:hasEnd/(time:inXSDDateTime|time:inXSDDate) ?endTime . }
      OPTIONAL { ?tempEntity (time:inXSDDateTime|time:inXSDDate) ?instantTime . }
    }
    UNION
    {
      ?hazard kwg-ont:hasDeclaration/kwg-ont:hasDeclarationDate/(time:inXSDDateTime|time:inXSDDate) ?instantTime .
    }
    UNION
    {
      OPTIONAL {
        ?obs_start sosa:hasFeatureOfInterest ?hazard ;
                     sosa:observedProperty kwgr:nifcFireObservableProperty.fireDiscoveryDateTime ;
                     sosa:hasSimpleResult ?startTime .
      }
      OPTIONAL {
        ?obs_end sosa:hasFeatureOfInterest ?hazard ;
                   sosa:observedProperty kwgr:nifcFireObservableProperty.fireOutDateTime ;
                   sosa:hasSimpleResult ?endTime .
      }
    }
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?author
WHERE {
  ?role rdf:type coresr-ont:Author ;
        coresr-ont:isPerformedBy ?author .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "earthquake") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "earthquake")
  )
}
ORDER BY ?attribute

