PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?damageImpactDetail ?temporalData
WHERE {
    ?damageImpactDetail rdf:type owl:DatatypeProperty .
    FILTER(CONTAINS(LCASE(STR(?damageImpactDetail)), "hurricane"))

    # Filter to only get the "base" properties in this variable.
    # A base property is not a sub-property of another hurricane-related property.
    FILTER NOT EXISTS {
        ?damageImpactDetail rdfs:subPropertyOf ?anotherProp .
        FILTER(CONTAINS(LCASE(STR(?anotherProp)), "hurricane"))
    }

    # Optionally find the temporal sub-properties for each base property.
    OPTIONAL {
        ?temporalData rdfs:subPropertyOf ?damageImpactDetail .
    }
}
ORDER BY ?damageImpactDetail ?temporalData

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hurricane ?hazardAttribute ?hazardValue ?spatialPredicate ?place ?impactProperty ?impactValue ?damageTime
WHERE {
  ?hurricane a kwg-ont:NOAAHurricane .

  OPTIONAL {
    ?magCollection sosa:hasFeatureOfInterest ?hurricane ;
                   a kwg-ont:MagnitudeObservationCollection .
    ?magCollection sosa:hasMember ?magObs .
    ?magObs sosa:observedProperty ?hazardAttribute .
    OPTIONAL { ?magObs sosa:hasSimpleResult ?hazardValue . }
  }

  OPTIONAL {
    VALUES ?spatialPredicate { geo:hasGeometry geo:hasDefaultGeometry kwg-ont:spatialRelation kwg-ont:sfWithin }
    ?hurricane ?spatialPredicate ?place .
  }

  OPTIONAL {
    ?impactCollection sosa:hasFeatureOfInterest ?hurricane ;
                      a kwg-ont:ImpactObservationCollection .
    ?impactCollection sosa:hasMember ?impactObs .
    ?impactObs sosa:observedProperty ?impactProperty .
    OPTIONAL { ?impactObs sosa:hasSimpleResult ?impactValue . }
    OPTIONAL { ?impactCollection sosa:phenomenonTime ?damageTime . }
  }
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  {
    ?place a geo:Feature .
    ?place rdfs:label ?name .
  }
  UNION
  {
    ?place a geo:Feature .
    ?place gnis:officialName ?name .
  }
  UNION
  {
    ?place a gnis:State .
    ?place gnis:stateName ?name .
  }
  UNION
  {
    ?place a gnis:County .
    ?place gnis:countyName ?name .
  }
  UNION
  {
    ?place a kwg-ont:Hospital .
    ?place kwg-ont:hospitalName ?name .
  }
  UNION
  {
    ?place a kwg-ont:AirQualitySite .
    ?place kwg-ont:siteName ?name .
  }
  UNION
  {
    ?place a kwg-ont:FederalJudicalDistrict .
    ?place kwg-ont:hasName ?name .
  }
}

