PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazard ?hazardType (SAMPLE(?placeName) AS ?affectedPlace) ?damageTypeLabel ?damageValue ?begin_time ?end_time
WHERE {
  VALUES ?damageType { kwgr:impactObservableProperty.damageProperty kwgr:impactObservableProperty.damageCrop }

  ?hazard a ?hazardType .
  ?hazardType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  FILTER NOT EXISTS { ?hazardType rdfs:subClassOf kwg-ont:NOAAHazard . }

  ?impactCollection a kwg-ont:ImpactObservationCollection ;
                    sosa:hasFeatureOfInterest ?hazard ;
                    sosa:hasMember ?impactObservation .

  ?impactObservation sosa:observedProperty ?damageType ;
                     sosa:hasSimpleResult ?damageValue .
  ?damageType rdfs:label ?damageTypeLabel .

  ?hazard kwg-ont:hasSegment/kwg-ont:startsFrom ?fix .
  ?fix kwg-ont:sfWithin ?place .
  ?place a kwg-ont:AdministrativeRegion_3 ;
         rdfs:label ?placeName .

  ?impactCollection sosa:phenomenonTime ?temporalEntity .
  ?temporalEntity time:hasBeginning/time:inXSDDateTime ?begin_time ;
                  time:hasEnd/time:inXSDDateTime ?end_time .

  FILTER(?begin_time >= "2017-01-01T00:00:00"^^xsd:dateTime && ?end_time < "2018-01-01T00:00:00"^^xsd:dateTime)
}
GROUP BY ?hazard ?hazardType ?damageTypeLabel ?damageValue ?begin_time ?end_time
ORDER BY ?begin_time ?affectedPlace

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?state ?university ?publicationCount
WHERE {
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?publicationCount)
    WHERE {
      ?university a coress-ont:University ;
                  coress-ont:atState ?state ;
                  coress-ont:hasCollege ?college .
      ?college coress-ont:hasDepartment ?department .
      ?department coress-ont:hasAgent ?agent .
      ?author coress-ont:isPerformedBy ?agent ;
              a coress-ont:Author .
      ?publication coress-ont:submittedBy ?author .
    }
    GROUP BY ?state ?university
  }
  {
    SELECT ?state (MAX(?pcount) AS ?maxCount)
    WHERE {
      {
        SELECT ?state (COUNT(DISTINCT ?publication) AS ?pcount)
        WHERE {
          ?university a coress-ont:University ;
                      coress-ont:atState ?state ;
                      coress-ont:hasCollege ?college .
          ?college coress-ont:hasDepartment ?department .
          ?department coress-ont:hasAgent ?agent .
          ?author coress-ont:isPerformedBy ?agent ;
                  a coress-ont:Author .
          ?publication coress-ont:submittedBy ?author .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  FILTER(?publicationCount = ?maxCount)
}
ORDER BY ?state

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazardEvent ?hazardName ?hazardTypeLabel ?placeName ?startDate ?endDate ?damageToCrops ?damageToInfrastructure ?numberOfDeaths ?affectedArea
WHERE {
  VALUES ?hazardType {
    kwglr:blizzard
    kwglr:dustStorm
    kwglr:hail
    kwglr:hurricane
    kwglr:iceStorm
    kwglr:marineHail
    kwglr:marineHighWind
    kwglr:marineStrongWind
    kwglr:marineThunderstormWind
    kwglr:marineTropicalDepression
    kwglr:marineTropicalStorm
    kwglr:stormSurgeTide
    kwglr:strongWind
    kwglr:thunderstormWind
    kwglr:tornado
    kwglr:tropicalDepression
    kwglr:tropicalStorm
    kwglr:waterspout
    kwglr:winterStorm
  }

  ?hazardEvent rdf:type kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType ?hazardType ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:hasStartDate ?startDate .

  FILTER(?startDate >= "2020-01-01"^^xsd:date && ?startDate < "2021-01-01"^^xsd:date)

  ?place kwgl-ont:hasName ?placeName .

  BIND(REPLACE(STR(?hazardType), "http://stko-kwg.geog.ucsb.edu/lod/lite/resource/", "") AS ?hazardTypeLabel)

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea . }
}
LIMIT 100

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?earthquake ?name ?hazardType ?startDate ?endDate ?deaths ?damageToCrops ?damageToInfrastructure ?affectedArea
WHERE {
  ?earthquake a kwgl-ont:Earthquake .
  OPTIONAL { ?earthquake kwgl-ont:hasName ?name . }
  OPTIONAL { ?earthquake kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

