PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?healthConcernOrAttribute
WHERE {
  {
    VALUES ?healthObservableClass {
      kwg-ont:PublicHealthObservableProperty
      kwg-ont:AirPollutant
      kwg-ont:ImpactObservableProperty
      kwg-ont:VulnerabilityObservableProperty
      kwg-ont:SmokePlumeObservableProperty
    }
    ?healthConcernOrAttribute a ?healthObservableClass .
  }
  UNION
  {
    VALUES ?healthConcernOrAttribute {
      kwg-ont:noHospitalBeds
      kwg-ont:traumaCareLevel
      kwg-ont:helipadAvailability
      kwg-ont:hospitalStatus
      kwg-ont:hospitalType
      kwg-ont:pharmacyType
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?property ?value ?dateTime ?startDateTime ?endDateTime
WHERE {
  ?hazard a ?hazardType .
  ?hazardType rdfs:subClassOf* kwg-ont:Hazard .
  ?hazard ?property ?value .
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temporalEntity .
    OPTIONAL {
      ?temporalEntity time:inXSDDateTime ?dateTime .
    }
    OPTIONAL {
      ?temporalEntity time:hasBeginning/time:inXSDDateTime ?startDateTime .
    }
    OPTIONAL {
      ?temporalEntity time:hasEnd/time:inXSDDateTime ?endDateTime .
    }
  }
}
ORDER BY ?hazard ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?attribute ?totalCount
WHERE {
    {
        SELECT DISTINCT ?attribute WHERE {
            ?obsCollection sosa:hasFeatureOfInterest ?tornado .
            ?tornado a kwg-ont:NOAATornado .
            ?obsCollection sosa:hasMember ?observation .
            ?observation sosa:observedProperty ?attribute .
        }
    }
    {
        SELECT (COUNT(DISTINCT ?attribute) AS ?totalCount) WHERE {
            ?obsCollection sosa:hasFeatureOfInterest ?tornado .
            ?tornado a kwg-ont:NOAATornado .
            ?obsCollection sosa:hasMember ?observation .
            ?observation sosa:observedProperty ?attribute .
        }
    }
}

