PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?predicate ?object ?dateTime
WHERE {
  ?hazard a/rdfs:subClassOf* kwg-ont:Hazard .
  ?hazard ?predicate ?object .
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temporalEntity .
    {
      ?temporalEntity time:inXSDDateTime ?dateTime .
    }
    UNION
    {
      ?temporalEntity time:hasBeginning/time:inXSDDateTime ?dateTime .
    }
  }
}

