  UNION
  {
    ?place a kwg-ont:HealthCareFacility .
    VALUES ?attribute {
        kwg-ont:hospitalName
        kwg-ont:hospitalType
        kwg-ont:hospitalStatus
        kwg-ont:noHospitalBeds
        kwg-ont:traumaCareLevel
        kwg-ont:helipadAvailability
        kwg-ont:pharmacyName
        kwg-ont:pharmacyType
        kwg-ont:publicHealthDepartmentName
        kwg-ont:hospitalAddress
        kwg-ont:telephoneNo
        kwg-ont:website
        kwg-ont:zipCode
