PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?hazard ?damageType ?damageValue
WHERE {
    ?obsCollection a kwg-ont:ImpactObservationCollection ;
                   sosa:hasFeatureOfInterest ?hazard ;
                   sosa:hasMember ?impactObs .
    ?hazard a kwg-ont:NOAAHazardEvent .
    ?impactObs sosa:observedProperty ?damageType ;
               sosa:hasSimpleResult ?damageValue .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hurricane ?placeName ?hurricaneName ?startDate ?endDate ?affectedArea ?deaths ?cropDamage ?infraDamage ?place_damage_property ?place_damage_value
WHERE {
  ?hurricane a kwgl-ont:Hurricane ;
             kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?hurricane kwgl-ont:hasName ?hurricaneName . }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
  OPTIONAL { ?hurricane kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hurricane kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hurricane kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hurricane kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hurricane kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hurricane kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }

  OPTIONAL {
    ?place ?place_damage_property ?place_damage_value .
    {
      ?place_damage_property rdfs:subPropertyOf* kwgl-ont:dollarDamageOfHurricanesImpactingPlace .
    } UNION {
      ?place_damage_property rdfs:subPropertyOf* kwgl-ont:numberOfHurricanesImpactingPlace .
    }
  }
}
ORDER BY ?placeName ?hurricaneName ?place_damage_property

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?tornado ?placeName ?startDate ?damageToCrops ?damageToInfrastructure ?deaths ?affectedArea ?placeTornadoDamage
WHERE {
  ?tornado a kwgl-ont:Tornado ;
           kwgl-ont:hasImpacted ?place ;
           kwgl-ont:hasStartDate ?startDate .

  ?place kwgl-ont:hasName ?placeName .

  # Define a certain temporal extent, e.g., between 2018 and 2022
  FILTER(?startDate >= "2018-01-01"^^xsd:date && ?startDate <= "2022-12-31"^^xsd:date)

  # Gather all available damage details using OPTIONAL
  OPTIONAL { ?tornado kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?tornado kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?tornado kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?tornado kwgl-ont:affectedAreaInAcres ?affectedArea . }

  # Find any available tornado damage property on the place
  OPTIONAL {
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace|kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018|kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019|kwgl-ont:dollarDamageOfTornadoesImpactingPlace2020|kwgl-ont:dollarDamageOfTornadoesImpactingPlace2021|kwgl-ont:dollarDamageOfTornadoesImpactingPlace2022 ?placeTornadoDamage .
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?placeName ?hazardEventName ?hazardTypeLabel ?startDate ?endDate ?deaths ?affectedArea ?cropDamage ?infraDamage
WHERE {
  ?hazardEvent kwgl-ont:hasHazardType ?hazardType ;
               kwgl-ont:hasImpacted ?place .

  VALUES ?hazardType { kwglr:flood kwglr:flashFlood kwglr:coastalFlood kwglr:lakeshoreFlood }

  ?hazardType rdfs:label ?hazardTypeLabel .
  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hazardEventName . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?author
WHERE {
  ?author a coresr-ont:Author .
