PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "hurricane") ||
    CONTAINS(LCASE(STR(?attribute)), "damage") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "damage")
  )
}
ORDER BY ?attribute

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?hazardName ?damageToCrops ?damageToInfrastructure ?numberOfDeaths ?affectedAreaInAcres
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  ?hazard kwgl-ont:hasImpacted [] .

  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }

  FILTER (BOUND(?damageToCrops) || BOUND(?damageToInfrastructure) || BOUND(?numberOfDeaths) || BOUND(?affectedAreaInAcres))
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?healthAttribute
WHERE {
  {
    # Health attributes as observable properties on geographical features
    ?obs sosa:hasFeatureOfInterest ?place ;
         sosa:observedProperty ?healthAttribute .
    ?place a geo:Feature .
    VALUES ?concernType {
      kwg-ont:PublicHealthObservableProperty
      kwg-ont:AirPollutant
      kwg-ont:SmokePlumeObservableProperty
      kwg-ont:VulnerabilityObservableProperty
      kwg-ont:ImpactObservableProperty
    }
    ?healthAttribute a ?concernType .
  }
  UNION
  {
    # Health attributes as direct properties of health care facilities
    ?place a kwg-ont:HealthCareFacility .
    ?place ?healthAttribute [] .
    VALUES ?healthAttribute {
      kwg-ont:hospitalStatus
      kwg-ont:hospitalType
      kwg-ont:noHospitalBeds
      kwg-ont:traumaCareLevel
      kwg-ont:helipadAvailability
      kwg-ont:pharmacyType
    }
  }
}
ORDER BY ?place ?healthAttribute

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?attribute ?totalCount
WHERE {
  {
    SELECT DISTINCT ?attribute
    WHERE {
        ?attribute a owl:DatatypeProperty .
        ?attribute rdfs:domain kwgl-ont:Place .
        FILTER (CONTAINS(LCASE(STR(?attribute)), "tornado"))
    }
  }
  {
    SELECT (COUNT(DISTINCT ?attr) as ?totalCount)
    WHERE {
        ?attr a owl:DatatypeProperty .
        ?attr rdfs:domain kwgl-ont:Place .
        FILTER (CONTAINS(LCASE(STR(?attr)), "tornado"))
    }
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?city ?university ?college
WHERE {
  ?university a coress-ont:University ;
              coress-ont:atCity ?city ;
              coress-ont:hasCollege ?college .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hurricaneName ?placeName ?attribute ?value ?startDate ?endDate
WHERE {
  ?hurricane a kwgl-ont:Hurricane ;
             kwgl-ont:hasImpacted ?place ;
             kwgl-ont:hasName ?hurricaneName .
  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL { ?hurricane kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hurricane kwgl-ont:hasEndDate ?endDate . }

  {
    ?hurricane ?attribute ?value .
    FILTER(?attribute IN (
        kwgl-ont:affectedAreaInAcres,
        kwgl-ont:damageToCropsInDollars,
        kwgl-ont:damageToInfrastructureInDollars,
        kwgl-ont:numberOfDeaths
    ))
  }
  UNION
  {
    ?place ?attribute ?value .
    ?attribute rdfs:subPropertyOf* ?damageType .
    FILTER(?damageType IN (
        kwgl-ont:dollarDamageOfHurricanesImpactingPlace,
        kwgl-ont:numberOfHurricanesImpactingPlace
    ))
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX qudt: <http://qudt.org/1.1/schema/qudt#>

SELECT DISTINCT
    ?hurricane
    ?hazardAttributeLabel ?hazardAttributeValue ?hazardUnitLabel
    ?placeName
    ?damageTypeLabel ?damageValue ?damageUnitLabel
    ?eventTime ?damageTime
WHERE {
    VALUES ?hurricaneType { kwg-ont:NOAAHurricane kwg-ont:NOAAMarineHurricaneTyphoon }
    ?hurricane a ?hurricaneType .

    OPTIONAL {
        {
            ?obsColl sosa:hasFeatureOfInterest ?hurricane ;
                     a kwg-ont:MagnitudeObservationCollection ;
                     sosa:hasMember ?obs .
        } UNION {
            ?noaaHazard kwg-ont:hasPart ?hurricane .
            ?noaaHazard kwg-ont:hasStormTrack/kwg-ont:hasStormTracklet ?tracklet .
            ?obsColl sosa:hasFeatureOfInterest ?tracklet ;
                     a kwg-ont:StormTrackletObservationCollection ;
                     sosa:hasMember ?obs .
        }
        ?obs sosa:observedProperty ?hazardAttribute ;
             sosa:hasResult ?result .
        ?hazardAttribute rdfs:label ?hazardAttributeLabel .
        ?result qudt:numericValue ?hazardAttributeValue .
        OPTIONAL { ?result qudt:unit/rdfs:label ?hazardUnitLabel . }
    }

    OPTIONAL {
        ?hurricane kwg-ont:spatialRelation ?place .
        ?place a kwg-ont:AdministrativeRegion_3 ;
               rdfs:label ?placeName .
    }

    OPTIONAL {
        ?impactColl sosa:hasFeatureOfInterest ?hurricane ;
                    a kwg-ont:ImpactObservationCollection ;
                    sosa:hasMember ?impactObs .
        ?impactObs sosa:observedProperty ?damageType ;
                   sosa:hasResult ?damageResult .
        ?damageType rdfs:label ?damageTypeLabel .
        ?damageResult qudt:numericValue ?damageValue .
        OPTIONAL { ?damageResult qudt:unit/rdfs:label ?damageUnitLabel . }

        OPTIONAL {
            ?impactColl sosa:phenomenonTime ?damageTimeEntity .
            ?damageTimeEntity (time:inXSDDateTime | (time:hasBeginning/time:inXSDDateTime)) ?damageTime .
        }
    }

    OPTIONAL {
        ?eventObsColl sosa:hasFeatureOfInterest ?hurricane .
        ?eventObsColl sosa:phenomenonTime ?eventTimeEntity .
        ?eventTimeEntity (time:inXSDDateTime | (time:hasBeginning/time:inXSDDateTime)) ?eventTime .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?attribute ?count
WHERE {
  {
    SELECT (COUNT(DISTINCT ?attr) AS ?count)
    WHERE {
      ?attr rdf:type ?propType .
      VALUES ?propType { kwg-ont:MagnitudeObservableProperty kwg-ont:ImpactObservableProperty }
    }
  }
  ?attribute rdf:type ?propType .
  VALUES ?propType { kwg-ont:MagnitudeObservableProperty kwg-ont:ImpactObservableProperty }
}
ORDER BY ?attribute

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
