SELECT ?place ?placeName ?floodAttribute ?value
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName .
  VALUES ?baseFloodProperty {
    kwgl-ont:dollarDamageOfFloodsImpactingPlace
    kwgl-ont:numberOfFloodsImpactingPlace
  }
  ?place ?floodAttribute ?value .
  ?floodAttribute rdfs:subPropertyOf* ?baseFloodProperty .
}

