PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  OPTIONAL {
    ?attribute rdfs:label ?attributeLabel .
  }
  OPTIONAL {
    ?attribute rdfs:range ?range .
  }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL {
      ?parentAttribute rdfs:label ?parentLabel .
    }
  }
  FILTER(CONTAINS(LCASE(STR(?attribute)), "earthquake") || CONTAINS(LCASE(?attributeLabel), "earthquake"))
}
ORDER BY ?attribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
