PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?damageObservation ?property ?value
WHERE {
  ?observationCollection sosa:hasFeatureOfInterest ?hazard ;
                         sosa:hasMember ?damageObservation .
  ?hazard a kwg-ont:NOAAHazardEvent .
  ?damageObservation a kwg-ont:ImpactObservation ;
                     sosa:observedProperty ?damageType ;
                     ?property ?value .
  FILTER (
    ?damageType = kwgr:impactObservableProperty.damageCrop ||
    ?damageType = kwgr:impactObservableProperty.damageProperty
  )
}
ORDER BY ?hazard ?damageObservation

