PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?firstName ?familyName ?advisor ?field ?pubTitle
WHERE {
  ?agent coress-ont:performsRole ?author ;
         coress-ont:hasFirstName ?firstName ;
         coress-ont:hasFamilyName ?familyName .
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor ;
          coress-ont:submits ?publication .
  ?publication coress-ont:hasTitle ?pubTitle ;
               coress-ont:associatedFieldOfStudy ?field .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazard ?property ?value ?timeInstant ?startTime ?endTime
WHERE {
  ?hazard a ?hazardClass .
  ?hazardClass rdfs:subClassOf* kwg-ont:Hazard .

  ?hazard ?property ?value .

  OPTIONAL {
    { ?hazard kwg-ont:hasTemporalScope ?tempEntity . }
    UNION
    { ?entity sosa:hasFeatureOfInterest ?hazard ;
              sosa:phenomenonTime ?tempEntity .
    }

    OPTIONAL { ?tempEntity (time:inXSDDateTime | time:inXSDDate | time:inXSDDateTimeStamp) ?timeInstant . }
    OPTIONAL { ?tempEntity time:hasBeginning/(time:inXSDDateTime | time:inXSDDate | time:inXSDDateTimeStamp) ?startTime . }
    OPTIONAL { ?tempEntity time:hasEnd/(time:inXSDDateTime | time:inXSDDate | time:inXSDDateTimeStamp) ?endTime . }
  }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?state ?university ?pubCount
WHERE {
  {
    SELECT ?state (MAX(?count) as ?maxCount)
    WHERE {
      SELECT ?state ?university (COUNT(DISTINCT ?publication) as ?count)
      WHERE {
        ?university a coresr-ont:University ;
                    coresr-ont:locatedAt ?location .
        ?location coresr-ont:atState ?state .

        ?university coresr-ont:hasPart/coresr-ont:hasPart/coresr-ont:hasAssociatedAgent ?agent .

        ?role coresr-ont:isPerformedBy ?agent .
        ?publication (coresr-ont:hasContributor | coresr-ont:submittedBy) ?role .
      }
      GROUP BY ?state ?university
    }
    GROUP BY ?state
  }

  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) as ?pubCount)
    WHERE {
      ?university a coresr-ont:University ;
                  coresr-ont:locatedAt ?location .
      ?location coresr-ont:atState ?state .

      ?university coresr-ont:hasPart/coresr-ont:hasPart/coresr-ont:hasAssociatedAgent ?agent .

      ?role coresr-ont:isPerformedBy ?agent .
      ?publication (coresr-ont:hasContributor | coresr-ont:submittedBy) ?role .
    }
    GROUP BY ?state ?university
  }

  FILTER(?pubCount = ?maxCount)
}
ORDER BY ?state ?university

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?hazardName ?hazardTypeLabel ?startDate ?endDate ?affectedArea ?cropDamage ?infraDamage ?deaths
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName . }
  OPTIONAL {
    ?hazard kwgl-ont:hasHazardType ?hazardType .
    ?hazardType rdfs:label ?hazardTypeLabel .
  }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
