PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?stormAttribute ?property ?value
WHERE {
  {
    ?stormAttribute rdfs:subClassOf* kwg-ont:StormTrackObservableProperty .
  }
  UNION
  {
    ?stormAttribute rdfs:subClassOf* kwg-ont:StormTrackletObservableProperty .
