PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hurricane ?geometry ?hazardAttribute ?hazardValue ?damageAttribute ?damageValue ?damageTime
WHERE {
  VALUES ?hurricaneType { kwg-ont:NOAAHurricane kwg-ont:NOAAMarineHurricaneTyphoon }
  ?hurricane a ?hurricaneType .

  ?hurricane geo:hasGeometry ?geometry .

  OPTIONAL {
    ?magObs sosa:hasFeatureOfInterest ?hurricane ;
            a kwg-ont:MagnitudeObservation ;
            sosa:observedProperty ?hazardAttribute ;
            sosa:hasSimpleResult ?hazardValue .
  }

  OPTIONAL {
    ?impactObs sosa:hasFeatureOfInterest ?hurricane ;
               a kwg-ont:ImpactObservation ;
               sosa:observedProperty ?damageAttribute ;
               sosa:hasSimpleResult ?damageValue .
    OPTIONAL { ?impactObs sosa:phenomenonTime ?damageTime . }
  }
}

