               coresr-ont:isPerformedBy ?advisorAgent .

  ?authorAgent coresr-ont:hasContactInformation ?authorNameInstance .
  ?authorNameInstance coresr-ont:nameAsString ?authorName .

  ?advisorAgent coresr-ont:hasContactInformation ?advisorNameInstance .
  ?advisorNameInstance coresr-ont:nameAsString ?advisorName .
