PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?placeName ?population ?households ?povertyPercent ?diabeticPercent ?obesePercent
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasName ?placeName .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyPercent . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabeticPercent . }
  OPTIONAL { ?place kwgl-ont:percentObese ?obesePercent . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT
  ?hazard
  ?name
  ?hazardType
  ?startDate
  ?endDate
  ?affectedArea
  ?deaths
  ?cropDamage
  ?infraDamage
WHERE {
  ?hazard rdf:type ?hazardClass .
  ?hazardClass rdfs:subClassOf* kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?earthquake ?name ?hazardTypeLabel ?startDate ?endDate ?numberOfDeaths ?damageToCrops ?damageToInfrastructure
WHERE {
  ?earthquake a kwgl-ont:Earthquake .
  ?earthquake kwgl-ont:hasHazardType ?hazardType .
  ?hazardType rdfs:label ?hazardTypeLabel .
  FILTER(CONTAINS(LCASE(?hazardTypeLabel), "earthquake"))

  OPTIONAL { ?earthquake kwgl-ont:hasName ?name . }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?healthAttribute
WHERE {
    {
        ?obsCollection a kwg-ont:PublicHealthObservationCollection ;
                       sosa:hasFeatureOfInterest ?place ;
                       sosa:hasMember [ sosa:observedProperty ?healthAttribute ] .
    }
    UNION
    {
        ?place a kwg-ont:Hospital ;
               ?p [] .
        VALUES ?healthAttribute {
            kwg-ont:noHospitalBeds
            kwg-ont:hospitalType
            kwg-ont:traumaCareLevel
            kwg-ont:hospitalStatus
            kwg-ont:helipadAvailability
        }
        FILTER (?p = ?healthAttribute)
    }
    UNION
    {
        ?obs a kwg-ont:AirQualityObservation ;
             sosa:observedProperty ?healthAttribute .
        ?obs sosa:madeBySensor/^sosa:hosts ?place .
        ?place a kwg-ont:AirQualitySite .
    }
    UNION
    {
        ?obsCollection a kwg-ont:ImpactObservationCollection ;
                       sosa:hasFeatureOfInterest ?place ;
                       sosa:hasMember [ sosa:observedProperty ?healthAttribute ] .
        ?healthAttribute a kwg-ont:ImpactObservableProperty .
    }
}

