PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publicationTitle ?publicationTypeString
WHERE {
    ?publication a coresr-ont:Publication ;
                 coresr-ont:hasTitle ?publicationTitle ;
                 coresr-ont:hasPublicationType ?publicationType .
    ?publicationType coresr-ont:typeAsString ?publicationTypeString .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?agent ?department
WHERE {
    ?agent coresr-ont:associatedWith ?department .
}

