PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?department
WHERE {
  ?department rdf:type coress-ont:Department .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT (GROUP_CONCAT(DISTINCT ?earthquakeHazard; separator=", ") AS ?allEarthquakeHazards) (COUNT(DISTINCT ?earthquakeHazard) AS ?numberOfHazards)
WHERE {
  ?earthquakeHazard a kwg-ont:Earthquake .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
    ?place
    ?placeName
    ?tornadoEvent
    ?startDate
    ?endDate
    ?eventCropDamage
    ?eventInfraDamage
    ?placeDamagePropertyLabel
    ?placeDamageValue
WHERE {
    ?tornadoEvent a kwgl-ont:Tornado ;
                  kwgl-ont:hasImpacted ?place .

    OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
    OPTIONAL { ?tornadoEvent kwgl-ont:hasStartDate ?startDate . }
    OPTIONAL { ?tornadoEvent kwgl-ont:hasEndDate ?endDate . }
    OPTIONAL { ?tornadoEvent kwgl-ont:damageToCropsInDollars ?eventCropDamage . }
    OPTIONAL { ?tornadoEvent kwgl-ont:damageToInfrastructureInDollars ?eventInfraDamage . }

    OPTIONAL {
        ?place ?placeDamageProperty ?placeDamageValue .
        ?placeDamageProperty rdfs:subPropertyOf* kwgl-ont:dollarDamageOfTornadoesImpactingPlace .
        OPTIONAL { ?placeDamageProperty rdfs:label ?placeDamagePropertyLabel . }
    }

    FILTER(BOUND(?eventCropDamage) || BOUND(?eventInfraDamage) || BOUND(?placeDamageValue))
}
ORDER BY ?placeName ?startDate

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?authorName ?advisorName
WHERE {
  ?agent a coress-ont:Agent ;
         coress-ont:performsRole ?authorRole ;
         coress-ont:hasFirstName ?firstName ;
         coress-ont:hasFamilyName ?familyName .
  ?authorRole a coress-ont:Author ;
              coress-ont:advisedBy ?advisorName .
  BIND(CONCAT(?firstName, " ", ?familyName) AS ?authorName)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardEvent ?impactPropertyLabel ?impactValue
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
  ?impactObs sosa:hasFeatureOfInterest ?hazardEvent ;
             a kwg-ont:ImpactObservation ;
             sosa:observedProperty ?impactProperty ;
             sosa:hasSimpleResult ?impactValue .
  ?impactProperty rdfs:label ?impactPropertyLabel .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?health_concern_or_attribute
WHERE {
  {
    # Find observable properties related to public health, air quality, vulnerability, and hazard impacts that are associated with a geographical feature.
    ?observation sosa:hasFeatureOfInterest ?place ;
                 sosa:observedProperty ?health_concern_or_attribute .
    ?place a geo:Feature .
    VALUES ?obs_type {
        kwg-ont:PublicHealthObservation
        kwg-ont:AirQualityObservation
        kwg-ont:VulnerabilityObservation
        kwg-ont:ImpactObservation
    }
    ?observation a ?obs_type .
  }
  UNION
  {
    # Find descriptive attributes of health care facilities, which are themselves geographical features.
    ?facility a kwg-ont:HealthCareFacility .
    VALUES ?health_concern_or_attribute {
        kwg-ont:hospitalType
        kwg-ont:hospitalStatus
        kwg-ont:traumaCareLevel
        kwg-ont:helipadAvailability
        kwg-ont:noHospitalBeds
        kwg-ont:pharmacyType
    }
    ?facility ?health_concern_or_attribute ?value .
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT (COUNT(DISTINCT ?attribute) AS ?numberOfTornadoAttributes) (GROUP_CONCAT(DISTINCT STR(?attribute); separator="; ") AS ?tornadoAttributes)
WHERE {
  ?place a kwgl-ont:Place ;
         ?attribute ?value .
  FILTER(CONTAINS(LCASE(STR(?attribute)), "tornado"))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "storm") ||
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "hurricane") ||
    CONTAINS(LCASE(STR(?attribute)), "tornado") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "tornado")
  )
}
ORDER BY ?attribute

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?agent ?department
WHERE {
  ?agent rdf:type coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
  ?department rdf:type coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
    ?department a coresr-ont:Department .
    ?department coresr-ont:hasAssociatedAgent ?agent .
    FILTER NOT EXISTS {
        ?agent coresr-ont:hasContactInformation ?contactInfo .
        ?contactInfo a coresr-ont:FamilyName .
    }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT (GROUP_CONCAT(DISTINCT STR(?earthquakeHazard); separator="; ") AS ?earthquakeHazards) (COUNT(DISTINCT ?earthquakeHazard) AS ?numberOfEarthquakeHazards)
WHERE {
  ?earthquakeHazard a kwgl-ont:Earthquake .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publicationTypeString (AVG(?publicationDate - ?submissionDate) AS ?avgTimeDifference)
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasPublicationType ?publicationType ;
               coresr-ont:dateOfSubmission ?submissionDate ;
               coresr-ont:dateOfPublication ?publicationDate .
  ?publicationType coresr-ont:typeAsString ?publicationTypeString .
}
GROUP BY ?publicationTypeString
ORDER BY DESC(?avgTimeDifference)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?hazardType ?startDate ?endDate ?deaths ?cropDamage ?infraDamage ?area
