  OPTIONAL {
    ?hazard kwgl-ont:hasHazardType ?hazardType .
  }
  OPTIONAL {
    ?hazard kwgl-ont:hasStartDate ?startDate .
  }
  OPTIONAL {
    ?hazard kwgl-ont:hasEndDate ?endDate .
  }
  OPTIONAL {
    ?hazard kwgl-ont:numberOfDeaths ?deaths .
  }
  OPTIONAL {
    ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage .
  }
  OPTIONAL {
    ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage .
  }
  OPTIONAL {
    ?hazard kwgl-ont:affectedAreaInAcres ?area .
  }
}
ORDER BY DESC(?startDate)

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?name ?type ?fireType ?startDate ?endDate ?deaths ?cropDamage ?infraDamage ?affectedArea
WHERE {
  ?hazard a/rdfs:subClassOf* kwgl-ont:HazardEvent .
  OPTIONAL {
    ?hazard kwgl-ont:hasName ?name .
  }
  OPTIONAL {
    ?hazard kwgl-ont:hasHazardType ?type .
  }
  OPTIONAL {
    ?hazard kwgl-ont:isOfFireType ?fireType .
  }
  OPTIONAL {
    ?hazard kwgl-ont:hasStartDate ?startDate .
  }
  OPTIONAL {
    ?hazard kwgl-ont:hasEndDate ?endDate .
  }
  OPTIONAL {
    ?hazard kwgl-ont:numberOfDeaths ?deaths .
  }
  OPTIONAL {
    ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage .
  }
  OPTIONAL {
    ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage .
  }
  OPTIONAL {
    ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea .
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT
  ?hurricane
  ?place
  ?hurricaneName
  ?placeName
  ?startDate
  ?endDate
  ?numberOfDeaths
  ?damageToCrops
  ?damageToInfrastructure
  ?affectedArea
  ?dollarDamageOfHurricanesImpactingPlace
  ?dollarDamageOfHurricanesImpactingPlace2018
  ?dollarDamageOfHurricanesImpactingPlace2019
  ?dollarDamageOfHurricanesImpactingPlace2020
  ?dollarDamageOfHurricanesImpactingPlace2021
  ?dollarDamageOfHurricanesImpactingPlace2022
  ?numberOfHurricanesImpactingPlace
  ?numberOfHurricanesImpactingPlace2018
  ?numberOfHurricanesImpactingPlace2019
  ?numberOfHurricanesImpactingPlace2020
  ?numberOfHurricanesImpactingPlace2021
  ?numberOfHurricanesImpactingPlace2022
WHERE {
  ?hurricane a kwgl-ont:Hurricane .
  ?hurricane kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?hurricane kwgl-ont:hasName ?hurricaneName . }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
  OPTIONAL { ?hurricane kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hurricane kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hurricane kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hurricane kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hurricane kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hurricane kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?dollarDamageOfHurricanesImpactingPlace2018 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?dollarDamageOfHurricanesImpactingPlace2019 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?dollarDamageOfHurricanesImpactingPlace2020 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?dollarDamageOfHurricanesImpactingPlace2021 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?dollarDamageOfHurricanesImpactingPlace2022 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?numberOfHurricanesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?numberOfHurricanesImpactingPlace2018 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?numberOfHurricanesImpactingPlace2019 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?numberOfHurricanesImpactingPlace2020 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?numberOfHurricanesImpactingPlace2021 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?numberOfHurricanesImpactingPlace2022 . }
}

PREFIX coresr: <http://www.corescholar.com/ontology/coresr-ont#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?typeName (AVG(?pubDate - ?subDate) AS ?avgTime)
WHERE {
  ?pub a coresr:Publication ;
       coresr:dateOfSubmission ?subDate ;
       coresr:dateOfPublication ?pubDate ;
       coresr:hasPublicationType ?pubType .
  ?pubType coresr:typeAsString ?typeName .
}
GROUP BY ?typeName
ORDER BY DESC(?avgTime)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?agent ?department
WHERE {
  ?agent rdf:type coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
  ?department rdf:type coresr-ont:Department .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?placeName ?attribute ?value
WHERE {
    ?place a kwgl-ont:Place .
    OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
    ?place ?attribute ?value .
    FILTER(regex(str(?attribute), "Storm", "i") || regex(str(?attribute), "Hurricane", "i") || regex(str(?attribute), "Tornado", "i"))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT
  ?hurricane ?place
  ?hurricane_name ?start_date ?end_date ?deaths ?affected_acres ?damage_to_crops ?damage_to_infrastructure
  ?dollar_damage_of_hurricanes_impacting_place ?dollar_damage_of_hurricanes_impacting_place_2018 ?dollar_damage_of_hurricanes_impacting_place_2019 ?dollar_damage_of_hurricanes_impacting_place_2020 ?dollar_damage_of_hurricanes_impacting_place_2021 ?dollar_damage_of_hurricanes_impacting_place_2022
WHERE {
  ?hurricane rdf:type kwgl-ont:Hurricane .
  ?hurricane kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?hurricane kwgl-ont:hasName ?hurricane_name . }
  OPTIONAL { ?hurricane kwgl-ont:hasStartDate ?start_date . }
  OPTIONAL { ?hurricane kwgl-ont:hasEndDate ?end_date . }
  OPTIONAL { ?hurricane kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hurricane kwgl-ont:affectedAreaInAcres ?affected_acres . }
  OPTIONAL { ?hurricane kwgl-ont:damageToCropsInDollars ?damage_to_crops . }
  OPTIONAL { ?hurricane kwgl-ont:damageToInfrastructureInDollars ?damage_to_infrastructure . }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollar_damage_of_hurricanes_impacting_place . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?dollar_damage_of_hurricanes_impacting_place_2018 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?dollar_damage_of_hurricanes_impacting_place_2019 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?dollar_damage_of_hurricanes_impacting_place_2020 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?dollar_damage_of_hurricanes_impacting_place_2021 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?dollar_damage_of_hurricanes_impacting_place_2022 . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?attributeLabel ?range ?parentAttribute ?parentLabel
WHERE {
  # Find datatype properties that are associated with kwgl-ont:Place in the schema
  kwgl-ont:Place ?attribute ?range .
  ?attribute rdf:type owl:DatatypeProperty .

  # Filter for properties related to hurricanes
  FILTER(CONTAINS(LCASE(STR(?attribute)), "hurricane"))

  # Get optional details for the attribute
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  # Find parent properties, which indicates temporal data as per the schema design
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }
}
ORDER BY ?attribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?healthConcernOrAttribute ?label WHERE {
    {
        # Health-related observable properties that are observed on geographical features
        ?observation sosa:hasFeatureOfInterest ?place .
        ?place a/rdfs:subClassOf* geo:Feature .
        ?observation sosa:observedProperty ?healthConcernOrAttribute .
        { ?observation a kwg-ont:PublicHealthObservation . }
        UNION
        { ?observation a kwg-ont:VulnerabilityObservation . }
        ?healthConcernOrAttribute rdfs:label ?label .
    }
    UNION
    {
        # Types of Health Care Facilities, which are themselves geographical places
        ?facility a ?healthConcernOrAttribute .
        ?healthConcernOrAttribute rdfs:subClassOf kwg-ont:HealthCareFacility ;
                                  rdfs:label ?label .
    }
    UNION
    {
        # Specific data properties of health care facilities
        ?facility a/rdfs:subClassOf* kwg-ont:HealthCareFacility .
        ?facility ?healthConcernOrAttribute ?value .
        VALUES ?healthConcernOrAttribute {
            kwg-ont:hospitalType
            kwg-ont:hospitalStatus
            kwg-ont:traumaCareLevel
            kwg-ont:noHospitalBeds
            kwg-ont:helipadAvailability
            kwg-ont:pharmacyType
            kwg-ont:administrativeLevel
        }
        ?healthConcernOrAttribute rdfs:label ?label .
    }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?damage_type ?damage_value
WHERE {
  ?impact_observation a kwg-ont:ImpactObservation ;
                      sosa:observedProperty ?damage_type ;
                      sosa:hasSimpleResult ?damage_value .
  ?damage_type a kwg-ont:ImpactObservableProperty .
  ?impact_collection sosa:hasMember ?impact_observation ;
                     sosa:hasFeatureOfInterest ?hazard .
  ?hazard a kwg-ont:Hazard .
}
ORDER BY ?hazard

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?state ?university ?publicationCount
WHERE {
  {
    SELECT ?state (MAX(?pCount) AS ?maxCount)
    WHERE {
      {
        SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?pCount)
        WHERE {
          ?publication coresr-ont:submittedBy ?author .
          ?author coresr-ont:isPerformedBy ?agent .
          ?agent coresr-ont:associatedWith ?department .
          ?department coresr-ont:partOf ?college .
          ?college coresr-ont:partOf ?university .
          ?university coresr-ont:locatedAt ?location .
          ?location coresr-ont:atState ?state .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?publicationCount)
    WHERE {
      ?publication coresr-ont:submittedBy ?author .
      ?author coresr-ont:isPerformedBy ?agent .
      ?agent coresr-ont:associatedWith ?department .
      ?department coresr-ont:partOf ?college .
      ?college coresr-ont:partOf ?university .
      ?university coresr-ont:locatedAt ?location .
      ?location coresr-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  FILTER(?publicationCount = ?maxCount)
}
ORDER BY ?state

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?typeName (AVG(?publicationDate - ?submissionDate) AS ?avgTimeDifference)
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate ;
               coresr-ont:dateOfPublication ?publicationDate ;
               coresr-ont:hasPublicationType ?pubType .
  ?pubType coresr-ont:typeAsString ?typeName .
}
GROUP BY ?typeName
ORDER BY DESC(?avgTimeDifference)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  ?attribute rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(?attributeLabel), "flood")
  )
}
ORDER BY ?attribute

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?author ?advisor
WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?author ?advisor
WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdfs:domain kwgl-ont:Place .
  ?attribute rdf:type owl:DatatypeProperty .

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "temperature") ||
    CONTAINS(LCASE(STR(?attribute)), "cooling") ||
    CONTAINS(LCASE(STR(?attribute)), "heating")
  )

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }
}
ORDER BY ?attribute

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?city ?university ?college
WHERE {
  ?university a coress-ont:University ;
              coress-ont:atCity ?city .
  ?college a coress-ont:College ;
           coress-ont:collegeOf ?university .
}
ORDER BY ?city

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent a coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?place ?health_concern_or_attribute ?value
WHERE {
  ?place a kwgl-ont:Place .
  ?place ?health_concern_or_attribute ?value .
  VALUES ?health_concern_or_attribute {
    kwgl-ont:percentDiabetic
    kwgl-ont:percentObese
    kwgl-ont:percentBelowPovertyLine
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?damageProperty
  ?propertyLabel
  ?domain
  ?range
WHERE {
  ?damageProperty rdf:type owl:DatatypeProperty .
  OPTIONAL {
    ?damageProperty rdfs:label ?propertyLabel .
  }
  OPTIONAL {
    ?damageProperty rdfs:domain ?domain .
  }
  OPTIONAL {
    ?damageProperty rdfs:range ?range .
  }
  FILTER (
    (
      CONTAINS(LCASE(STR(?damageProperty)), "damage") && CONTAINS(LCASE(STR(?damageProperty)), "tornado")
    ) || (
      ?damageProperty rdfs:domain kwgl-ont:HazardEvent .
      FILTER(CONTAINS(LCASE(STR(?damageProperty)), "damage") || CONTAINS(LCASE(STR(?damageProperty)), "deaths") || CONTAINS(LCASE(STR(?damageProperty)), "acres"))
    )
  )
}
ORDER BY ?damageProperty

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?storm_hazard ?storm_type ?place ?damage_type ?damage_value ?start_time ?end_time
WHERE {
  ?impact_obs a kwg-ont:ImpactObservation;
              sosa:observedProperty ?damage_type;
              sosa:simpleResult ?damage_value.

  ?impact_obs_collection sosa:hasMember ?impact_obs;
                         sosa:hasFeatureOfInterest ?storm_hazard;
                         sosa:phenomenonTime ?temporal_entity.

  ?storm_hazard a ?storm_type.
  VALUES ?storm_type {
      kwg-ont:NOAAStormSurgeTide
      kwg-ont:NOAAHurricane
      kwg-ont:NOAATornado
      kwg-ont:NOAAThunderstormWind
      kwg-ont:NOAATropicalStorm
      kwg-ont:NOAAWinterStorm
      kwg-ont:NOAAMarineHurricaneTyphoon
      kwg-ont:NOAAMarineTropicalStorm
  }

  ?damage_type rdfs:subClassOf* kwg-ont:ImpactObservableProperty.

  ?storm_hazard kwg-ont:sfWithin ?place.
  ?place a kwg-ont:AdministrativeRegion.

  OPTIONAL {
    ?temporal_entity time:hasBeginning/time:inXSDDateTime ?start_time.
    ?temporal_entity time:hasEnd/time:inXSDDateTime ?end_time.
  }
  OPTIONAL {
    ?temporal_entity time:inXSDDateTime ?instant_time.
  }

  BIND(COALESCE(?start_time, ?instant_time) AS ?filter_time)

  FILTER(?filter_time >= "2020-01-01T00:00:00Z"^^xsd:dateTime && ?filter_time < "2021-01-01T00:00:00Z"^^xsd:dateTime)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?hazardName ?hazardType ?startDate ?endDate ?affectedArea ?cropDamage ?infraDamage ?deaths
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?state ?university ?pubCount
WHERE {
  {
    SELECT ?state (MAX(?count) AS ?maxCount)
    WHERE {
      SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?count)
      WHERE {
        ?university rdf:type coresr-ont:University;
                    coresr-ont:locatedAt ?location .
        ?location coresr-ont:atState ?state .
        ?college coresr-ont:partOf ?university .
        ?department coresr-ont:partOf ?college .
        ?agent coresr-ont:associatedWith ?department .
        ?author rdf:type coresr-ont:Author ;
                coresr-ont:isPerformedBy ?agent .
        ?publication coresr-ont:submittedBy ?author .
      }
      GROUP BY ?state ?university
    }
    GROUP BY ?state
  }
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?pubCount)
    WHERE {
      ?university rdf:type coresr-ont:University;
                  coresr-ont:locatedAt ?location .
      ?location coresr-ont:atState ?state .
      ?college coresr-ont:partOf ?university .
      ?department coresr-ont:partOf ?college .
      ?agent coresr-ont:associatedWith ?department .
      ?author rdf:type coresr-ont:Author ;
              coresr-ont:isPerformedBy ?agent .
      ?publication coresr-ont:submittedBy ?author .
    }
    GROUP BY ?state ?university
  }
  FILTER(?pubCount = ?maxCount)
}
ORDER BY ?state

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "damage") &&
    (
      CONTAINS(LCASE(STR(?attribute)), "storm") ||
      CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
      CONTAINS(LCASE(STR(?attribute)), "tornado")
    )
  )
}
ORDER BY ?attribute

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?placeName ?percentDiabetic ?percentObese ?percentBelowPovertyLine
WHERE {
  ?place kwgl-ont:hasName ?placeName .
  OPTIONAL {
    ?place kwgl-ont:percentDiabetic ?percentDiabetic .
  }
  OPTIONAL {
    ?place kwgl-ont:percentObese ?percentObese .
  }
  OPTIONAL {
    ?place kwgl-ont:percentBelowPovertyLine ?percentBelowPovertyLine .
  }
  FILTER(BOUND(?percentDiabetic) || BOUND(?percentObese) || BOUND(?percentBelowPovertyLine))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?placeName ?hazardType ?startDate ?endDate ?cropDamage ?infraDamage ?deaths ?affectedAcres
WHERE {
  VALUES ?hazardType {
    kwglr:blizzard kwglr:dustStorm kwglr:hail kwglr:heavyRain kwglr:heavySnow
    kwglr:highWind kwglr:hurricane kwglr:iceStorm kwglr:lightning kwglr:marineHail
    kwglr:marineHighWind kwglr:marineStrongWind kwglr:marineThunderstormWind
    kwglr:marineTropicalDepression kwglr:marineTropicalStorm kwglr:stormSurgeTide
    kwglr:strongWind kwglr:thunderstormWind kwglr:tornado kwglr:tropicalDepression
    kwglr:tropicalStorm kwglr:waterspout kwglr:winterStorm
  }
  ?hazardEvent a kwgl-ont:HazardEvent ;
    kwgl-ont:hasHazardType ?hazardType ;
    kwgl-ont:hasImpacted ?place ;
    kwgl-ont:hasStartDate ?startDate .
  ?place kwgl-ont:hasName ?placeName .
  FILTER(?startDate >= "2020-01-01"^^xsd:date && ?startDate < "2021-01-01"^^xsd:date)
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAcres . }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?geographicalPlace ?demographicAttribute ?value
WHERE {
  ?obsCollection a kwg-ont:CensusACS5YearEstimatesObservationCollection ;
                 sosa:hasFeatureOfInterest ?geographicalPlace ;
                 sosa:hasMember ?observation .
  ?observation sosa:observedProperty ?demographicAttribute ;
               sosa:hasSimpleResult ?value .
  ?demographicAttribute a kwg-ont:CensusObservableProperty .
  ?geographicalPlace a geo:Feature .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazard
  ?place
  ?damageProperty
  ?damageValue
  ?startDate
  ?endDate
WHERE {
  ?hazard a kwgl-ont:Tornado ;
          kwgl-ont:hasImpacted ?place .
  OPTIONAL {
    ?hazard kwgl-ont:hasStartDate ?startDate .
  }
  OPTIONAL {
    ?hazard kwgl-ont:hasEndDate ?endDate .
  }
  {
    ?place ?damageProperty ?damageValue .
    ?damageProperty rdfs:subPropertyOf* kwgl-ont:dollarDamageOfTornadoesImpactingPlace .
  }
  UNION
  {
    ?hazard ?damageProperty ?damageValue .
    VALUES ?damageProperty {
      kwgl-ont:damageToCropsInDollars
      kwgl-ont:damageToInfrastructureInDollars
    }
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?typeName (AVG(?publicationDate - ?submissionDate) AS ?avgTimeDifference)
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate ;
               coresr-ont:dateOfPublication ?publicationDate ;
               coresr-ont:hasPublicationType ?pubType .
  ?pubType coresr-ont:typeAsString ?typeName .
}
GROUP BY ?typeName
ORDER BY DESC(?avgTimeDifference)

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?tornadoAttribute (COUNT(?allTornadoAttributes) as ?totalCount)
WHERE {
  {
    SELECT DISTINCT ?tornadoAttribute
    WHERE {
      ?tornadoAttribute a owl:DatatypeProperty ;
                        rdfs:domain kwgl-ont:Place .
      FILTER(CONTAINS(STR(?tornadoAttribute), "Tornadoes"))
    }
  }
  {
    SELECT ?allTornadoAttributes
    WHERE {
      ?allTornadoAttributes a owl:DatatypeProperty ;
                           rdfs:domain kwgl-ont:Place .
      FILTER(CONTAINS(STR(?allTornadoAttributes), "Tornadoes"))
    }
  }
}
GROUP BY ?tornadoAttribute
ORDER BY ?tornadoAttribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard_attribute ?damage_impact_detail ?temporal_data
WHERE {
  ?hurricane a ?hurricane_type .
  VALUES ?hurricane_type { kwg-ont:NOAAHurricane kwg-ont:NOAAMarineHurricaneTyphoon }
  ?obs_collection sosa:hasFeatureOfInterest ?hurricane .
  OPTIONAL {
    ?obs_collection sosa:phenomenonTime ?time_entity .
    OPTIONAL {
      ?time_entity time:inXSDDateTime ?datetime .
    }
    BIND(COALESCE(?datetime, ?time_entity) AS ?temporal_data)
  }
  {
    ?obs_collection a kwg-ont:MagnitudeObservationCollection ;
      sosa:hasMember ?observation .
    ?observation sosa:observedProperty ?hazard_attribute .
  }
  UNION
  {
    ?obs_collection a kwg-ont:ImpactObservationCollection ;
      sosa:hasMember ?observation .
    ?observation sosa:observedProperty ?damage_impact_detail .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?attributeLabel ?range
WHERE {
  ?attribute a owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  FILTER (
    REGEX(STR(?attribute), "Temperature|Heating|Cooling|Degree", "i") ||
    (BOUND(?attributeLabel) && REGEX(?attributeLabel, "Temperature|Heating|Cooling|Degree", "i"))
  )
}
ORDER BY ?attribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazard_attribute ?attribute_detail ?geographical_place
WHERE {
  VALUES ?storm_property_type {
    kwg-ont:StormTrackObservableProperty
    kwg-ont:StormTrackletObservableProperty
    kwg-ont:MagnitudeObservableProperty
  }

  ?hazard_attribute rdfs:subClassOf* ?storm_property_type .

  ?observation sosa:observedProperty ?hazard_attribute ;
               sosa:hasSimpleResult ?attribute_detail ;
               sosa:hasFeatureOfInterest ?storm_hazard .

  VALUES ?storm_type {
    kwg-ont:StormTrack
    kwg-ont:StormTracklet
    kwg-ont:NOAAHazardEvent
  }

  ?storm_hazard a/rdfs:subClassOf* ?storm_type .

  OPTIONAL {
    ?storm_hazard kwg-ont:spatialRelation ?geographical_place .
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?place ?placeName ?startDate ?endDate ?cropDamage ?infraDamage ?deaths ?affectedArea
WHERE {
  ?hazard a kwgl-ont:Tornado ;
          kwgl-ont:hasImpacted ?place ;
          kwgl-ont:hasStartDate ?startDate ;
          kwgl-ont:hasEndDate ?endDate .

  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }

  FILTER (?startDate >= "2021-01-01"^^xsd:date && ?endDate <= "2021-12-31"^^xsd:date)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?publication ?publicationType
WHERE {
  ?publication rdf:type coress-ont:Publication ;
               coress-ont:hasPublicationType ?publicationType .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hurricaneEvent ?hazardAttributeLabel ?hazardValue ?damageTypeLabel ?damageValue ?damageTimeValue
WHERE {
  VALUES ?hurricaneType {
    kwg-ont:NOAAHurricane
    kwg-ont:NOAAMarineHurricaneTyphoon
  }
  ?hurricaneEvent a ?hurricaneType .

  # Ensure the event is related to a geographical place via its segments/path
  ?hurricaneEvent kwg-ont:hasSegment/kwg-ont:startsFrom ?fix .

  # Retrieve hurricane-specific hazard attributes from Magnitude Observations
  OPTIONAL {
    ?magCollection sosa:hasFeatureOfInterest ?hurricaneEvent ;
                   a kwg-ont:MagnitudeObservationCollection .
    ?magCollection sosa:hasMember ?magObs .
    ?magObs sosa:observedProperty ?hazardAttribute ;
            sosa:hasSimpleResult ?hazardValue .
    ?hazardAttribute rdfs:label ?hazardAttributeLabel .
  }

  # Retrieve damage impact details
  OPTIONAL {
    ?impactCollection sosa:hasFeatureOfInterest ?hurricaneEvent ;
                      a kwg-ont:ImpactObservationCollection .
    ?impactCollection sosa:hasMember ?damageObs .
    ?damageObs sosa:observedProperty ?damageType ;
               sosa:hasSimpleResult ?damageValue .
    ?damageType rdfs:label ?damageTypeLabel .

    # Retrieve temporal data for the damage if available
    OPTIONAL {
      ?impactCollection sosa:phenomenonTime ?damageTime .
      ?damageTime (time:inXSDDate | time:inXSDDateTime) ?damageTimeValue .
    }
  }

  # Ensure at least one piece of attribute or damage information is found
  FILTER(BOUND(?hazardValue) || BOUND(?damageValue))
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiValue
WHERE {
  ?publication coresr-ont:hasIdentifier ?doi .
  ?doi coresr-ont:doiAsString ?doiValue .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricaneHazardAttribute ?damageImpactDetail ?temporalProperty
WHERE {
  {
    # Hurricane-specific hazard attributes are observable properties from Magnitude and StormTracklet observations.
    # These are linked to NOAAHurricane (via its superclass NOAAHazardEvent) and associated storm tracks.
    ?hurricaneHazardAttribute rdfs:subClassOf* kwg-ont:MagnitudeObservableProperty .
  }
  UNION
  {
    ?hurricaneHazardAttribute rdfs:subClassOf* kwg-ont:StormTrackletObservableProperty .
  }
  UNION
  {
    # Damage impact details are from ImpactObservations, which are also linked to NOAAHazardEvent.
    ?damageImpactDetail rdfs:subClassOf* kwg-ont:ImpactObservableProperty .
  }
  UNION
  {
    # The temporal property associated with the observation collections.
    VALUES ?temporalProperty { sosa:phenomenonTime }
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?city ?university ?college
WHERE {
    ?university coress-ont:atCity ?city ;
                coress-ont:hasCollege ?college .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?placeName ?attributeName
WHERE {
  ?place a kwg-ont:USCensusMSA ;
         rdfs:label ?placeName .

  ?obsCollection sosa:hasFeatureOfInterest ?place ;
                 sosa:hasMember ?observation .

  ?observation sosa:observedProperty ?demographicAttribute .

  ?demographicAttribute a kwg-ont:CensusObservableProperty ;
                        rdfs:label ?attributeName .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?tornadoHazard ?damageType ?damageValue ?geometry ?startTime ?endTime
WHERE {
  ?tornadoHazard a kwg-ont:NOAATornado ;
                 geo:hasGeometry ?geometry ;
                 kwg-ont:hasTemporalScope ?temporalEntity .

  ?impactObservation sosa:hasFeatureOfInterest ?tornadoHazard ;
                     sosa:observedProperty ?damageType ;
                     sosa:hasSimpleResult ?damageValue .

  OPTIONAL { 
    ?temporalEntity time:hasBeginning ?beginInstant .
    ?beginInstant time:inXSDDateTime ?startTime .
  }
  OPTIONAL { 
    ?temporalEntity time:hasEnd ?endInstant .
    ?endInstant time:inXSDDateTime ?endTime .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?concern
WHERE {
    {
        ?collection a kwg-ont:PublicHealthObservationCollection ;
                    sosa:hasFeatureOfInterest ?place ;
                    sosa:hasMember/sosa:observedProperty ?concern .
    }
    UNION
    {
        ?collection a kwg-ont:AirQualityObservationCollection ;
                    sosa:observedProperty ?concern ;
                    sosa:madeBySensor ?instrument .
        ?place sosa:hosts ?instrument ;
               a kwg-ont:AirQualitySite .
        ?concern rdfs:subClassOf* kwg-ont:AirPollutant .
    }
    UNION
    {
        ?observation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?place ;
                     sosa:observedProperty ?concern .
        FILTER(?concern IN (kwgr:impactObservableProperty.deathDirect, kwgr:impactObservableProperty.deathIndirect, kwgr:impactObservableProperty.injuryDirect, kwgr:impactObservableProperty.injuryIndirect))
    }
    UNION
    {
        ?observation a kwg-ont:VulnerabilityObservation ;
                     sosa:hasFeatureOfInterest ?place ;
                     sosa:observedProperty ?concern .
    }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?placeName ?hazardName ?hazardTypeLabel ?damageToCrops ?damageToInfrastructure ?numberOfDeaths ?dollarDamageOfStormSurges ?numberOfStormSurges ?dollarDamageOfTornadoes ?numberOfTornadoes ?dollarDamageOfHurricanes ?numberOfHurricanes
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:impactedBy ?hazardEvent ;
         kwgl-ont:hasName ?placeName .

  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType ?hazardType ;
               kwgl-ont:hasName ?hazardName .

  VALUES ?hazardType {
    kwglr:stormSurgeTide
    kwglr:strongWind
    kwglr:thunderstormWind
    kwglr:tornado
    kwglr:hurricane
    kwglr:tropicalStorm
    kwglr:winterStorm
    kwglr:iceStorm
    kwglr:blizzard
  }

  ?hazardType rdfs:label ?hazardTypeLabel .

  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfStormSurges . }
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?numberOfStormSurges . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageOfTornadoes . }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?numberOfTornadoes . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanes . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?numberOfHurricanes . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?hazardAttribute ?count
WHERE {
  {
    SELECT DISTINCT ?hazardAttribute 
    WHERE {
      VALUES ?propertyType { kwg-ont:MagnitudeObservableProperty kwg-ont:ImpactObservableProperty }
      ?hazardAttribute rdfs:subClassOf+ ?propertyType .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?attr) AS ?count) 
    WHERE {
      VALUES ?propertyType { kwg-ont:MagnitudeObservableProperty kwg-ont:ImpactObservableProperty }
      ?attr rdfs:subClassOf+ ?propertyType .
    }
  }
}
ORDER BY ?hazardAttribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>

SELECT DISTINCT ?place ?name WHERE {
  {
    ?place a/rdfs:subClassOf* geo:Feature .
  }
  UNION
  {
    ?place a/rdfs:subClassOf* usgs:Feature .
  }
  UNION
  {
    ?place a/rdfs:subClassOf* kwg-ont:Region .
  }
  ?place (rdfs:label|gnis:officialName|kwg-ont:hasName|kwg-ont:hospitalName|kwg-ont:pharmacyName|kwg-ont:siteName|kwg-ont:climateDivisionName|gnis:countyName|gnis:stateName) ?name .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?placeName ?hazardName ?hazardTypeLabel ?startDate ?endDate ?numberOfDeaths ?damageToCrops ?damageToInfrastructure ?affectedArea
WHERE {
  ?hazard kwgl-ont:hasHazardType ?hazardType .
  ?hazardType rdfs:label ?hazardTypeLabel .
  FILTER (
    CONTAINS(LCASE(?hazardTypeLabel), "storm") ||
    CONTAINS(LCASE(?hazardTypeLabel), "hurricane") ||
    CONTAINS(LCASE(?hazardTypeLabel), "tornado") ||
    CONTAINS(LCASE(?hazardTypeLabel), "blizzard") ||
    CONTAINS(LCASE(?hazardTypeLabel), "thunderstorm") ||
    CONTAINS(LCASE(?hazardTypeLabel), "tropical") ||
    CONTAINS(LCASE(?hazardTypeLabel), "waterspout") ||
    CONTAINS(LCASE(?hazardTypeLabel), "funnel")
  )

  ?hazard kwgl-ont:hasImpacted ?place ;
          kwgl-ont:hasName ?hazardName .
  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?state ?university ?pubCount
WHERE {
    {
        SELECT ?state (MAX(?count) as ?maxCount)
        WHERE {
            {
                SELECT ?state ?university (COUNT(DISTINCT ?publication) as ?count)
                WHERE {
                    ?publication coresr-ont:submittedBy ?author .
                    ?agent coresr-ont:performsRole ?author .
                    ?agent coresr-ont:associatedWith ?department .
                    ?department coresr-ont:partOf ?college .
                    ?college coresr-ont:partOf ?university .
                    ?university coresr-ont:locatedAt ?location .
                    ?location coresr-ont:atState ?state .
                }
                GROUP BY ?state ?university
            }
        }
        GROUP BY ?state
    }
    {
        SELECT ?state ?university (COUNT(DISTINCT ?publication) as ?pubCount)
        WHERE {
            ?publication coresr-ont:submittedBy ?author .
            ?agent coresr-ont:performsRole ?author .
            ?agent coresr-ont:associatedWith ?department .
            ?department coresr-ont:partOf ?college .
            ?college coresr-ont:partOf ?university .
            ?university coresr-ont:locatedAt ?location .
            ?location coresr-ont:atState ?state .
        }
        GROUP BY ?state ?university
    }
    FILTER(?pubCount = ?maxCount)
}
ORDER BY ?state

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department ?missingNameCount
WHERE {
  # Subquery to calculate the count of agents with missing family names for each department.
  {
    SELECT ?department (COUNT(?agent) AS ?missingNameCount)
    WHERE {
      ?agent a coress-ont:Agent ;
             coress-ont:worksInDepartment ?department .
      FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName . }
    }
    GROUP BY ?department
  }
  # Subquery to find the overall maximum count among all departments.
  {
    SELECT (MAX(?count) AS ?maxCount)
    WHERE {
      {
        SELECT (COUNT(?agent) AS ?count)
        WHERE {
          ?agent a coress-ont:Agent ;
                 coress-ont:worksInDepartment ?department .
          FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName . }
        }
        GROUP BY ?department
      }
    }
  }
  # Filter the results to include only those departments whose count matches the maximum count.
  FILTER(?missingNameCount = ?maxCount)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author
WHERE {
  ?author a coress-ont:Author .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT (GROUP_CONCAT(DISTINCT STR(?earthquakeHazard); separator="; ") AS ?earthquakeHazards) (COUNT(DISTINCT ?earthquakeHazard) AS ?count)
WHERE {
  ?earthquakeHazard rdfs:subClassOf* kwg-ont:Earthquake .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?hazardEvent
  ?hazardName
  ?hazardType
  ?place
  ?placeName
  ?startDate
  ?endDate
  ?cropDamage
  ?infraDamage
  ?deaths
  ?affectedArea
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType ?hazardType ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:hasStartDate ?startDate .

  FILTER(
    REGEX(STR(?hazardType), "Storm|Wind|Tornado|Hurricane|Blizzard|Tropical|Surge", "i")
  )

  FILTER(?startDate >= "2020-01-01"^^xsd:date && ?startDate <= "2021-12-31"^^xsd:date)

  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea . }
}
ORDER BY DESC(?startDate) ?placeName

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT
  ?hazardEvent
  ?place
  ?startDate
  ?endDate
  ?damageToCrops
  ?damageToInfrastructure
  ?deaths
  ?placeDamageProperty
  ?damageValue
WHERE {
  ?hazardEvent kwgl-ont:hasHazardType kwglr:tornado ;
               kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }

  OPTIONAL {
    {
      ?place ?p ?damageValue .
      ?p rdfs:subPropertyOf* kwgl-ont:dollarDamageOfTornadoesImpactingPlace .
      BIND(?p AS ?placeDamageProperty)
    }
    UNION
    {
      ?place ?p ?damageValue .
      ?p rdfs:subPropertyOf* kwgl-ont:numberOfTornadoesImpactingPlace .
      BIND(?p AS ?placeDamageProperty)
    }
  }
}
ORDER BY ?place ?hazardEvent

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?placeName ?healthConcern ?value
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName .

  VALUES ?healthConcern {
    kwgl-ont:percentDiabetic
    kwgl-ont:percentObese
    kwgl-ont:percentBelowPovertyLine
  }

  ?place ?healthConcern ?value .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department (COUNT(DISTINCT ?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?contactInfo .
    ?contactInfo a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS {
    ?agent coress-ont:hasFamilyName ?familyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?hazardName ?placeName ?startDate ?endDate ?damageToCrops ?damageToInfrastructure ?numberOfDeaths
WHERE {
  ?hazardEvent kwgl-ont:hasHazardType ?hazardType ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:hasStartDate ?startDate ;
               kwgl-ont:hasName ?hazardName .

  VALUES ?hazardType {
    kwglr:stormSurgeTide kwglr:thunderstormWind kwglr:tornado
    kwglr:tropicalDepression kwglr:tropicalStorm kwglr:hurricane
    kwglr:blizzard kwglr:dustStorm kwglr:iceStorm
    kwglr:marineThunderstormWind kwglr:winterStorm
  }

  ?place kwgl-ont:hasName ?placeName .

  FILTER(?startDate >= "2021-01-01"^^xsd:date && ?startDate <= "2021-12-31"^^xsd:date)

  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT (COUNT(?earthquakeHazard) AS ?count)
WHERE {
  ?earthquakeHazard rdf:type kwgl-ont:Earthquake .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiValue
WHERE {
  ?publication coresr-ont:hasIdentifier ?doi .
  ?doi coresr-ont:doiAsString ?doiValue .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?university ?pubCount
WHERE {
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?pubCount)
    WHERE {
      ?university a coresr-ont:University ;
                  coresr-ont:locatedAt ?location .
      ?location coresr-ont:atState ?state .
      ?college coresr-ont:partOf ?university .
      ?department coresr-ont:partOf ?college .
      ?agent coresr-ont:associatedWith ?department ;
             coresr-ont:performsRole ?authorRole .
      ?authorRole a coresr-ont:Author .
      ?publication coresr-ont:submittedBy ?authorRole .
    }
    GROUP BY ?state ?university
  }
  {
    SELECT ?state (MAX(?count) AS ?maxCount)
    WHERE {
      {
        SELECT ?state (COUNT(DISTINCT ?publication) AS ?count)
        WHERE {
          ?university a coresr-ont:University ;
                      coresr-ont:locatedAt ?location .
          ?location coresr-ont:atState ?state .
          ?college coresr-ont:partOf ?university .
          ?department coresr-ont:partOf ?college .
          ?agent coresr-ont:associatedWith ?department ;
                 coresr-ont:performsRole ?authorRole .
          ?authorRole a coresr-ont:Author .
          ?publication coresr-ont:submittedBy ?authorRole .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  FILTER(?pubCount = ?maxCount)
}
ORDER BY ?state

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?tornado ?place ?cropDamage ?infraDamage ?deaths ?affectedArea ?startDate ?endDate
WHERE {
  ?tornado a kwgl-ont:Tornado ;
           kwgl-ont:hasImpacted ?place ;
           kwgl-ont:hasStartDate ?startDate ;
           kwgl-ont:hasEndDate ?endDate .

  FILTER(?startDate >= "2020-01-01"^^xsd:date && ?endDate <= "2021-12-31"^^xsd:date)

  OPTIONAL { ?tornado kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?tornado kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?tornado kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?tornado kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?authorName ?field
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy [] ;
          coress-ont:submits ?publication .

  ?publication coress-ont:associatedFieldOfStudy ?field .

  ?agent coress-ont:performsRole ?author ;
         coress-ont:hasFirstName ?firstName ;
         coress-ont:hasFamilyName ?familyName .
  BIND(CONCAT(?firstName, " ", ?familyName) AS ?authorName) .
}
ORDER BY ?authorName ?field

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?firstName ?familyName ?field (GROUP_CONCAT(DISTINCT ?pubTitle; SEPARATOR=", ") AS ?publications)
WHERE {
  ?author a coress-ont:Author;
    coress-ont:advisedBy ?advisor;
    coress-ont:submits ?publication.
  ?author coress-ont:isPerformedBy ?agent.
  ?agent coress-ont:hasFirstName ?firstName;
    coress-ont:hasFamilyName ?familyName.
  ?publication coress-ont:associatedFieldOfStudy ?field;
    coress-ont:hasTitle ?pubTitle.
}
GROUP BY ?firstName ?familyName ?field
ORDER BY ?familyName ?firstName ?field

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardEvent ?eventName ?affectedArea ?cropDamage ?infraDamage ?deaths
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  ?hazardEvent kwgl-ont:hasName ?eventName .
  OPTIONAL {
    ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea .
  }
  OPTIONAL {
    ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage .
  }
  OPTIONAL {
    ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage .
  }
  OPTIONAL {
    ?hazardEvent kwgl-ont:numberOfDeaths ?deaths .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  VALUES ?domain { kwgl-ont:Place kwgl-ont:HazardEvent }
  ?attribute rdfs:domain ?domain .

  ?attribute rdf:type owl:DatatypeProperty .

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attribute)), "damage")
  )

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }
}
ORDER BY ?attribute

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?state ?university ?publicationCount
WHERE {
  {
    SELECT ?state (MAX(?pCount) AS ?maxPublicationCount)
    WHERE {
      SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?pCount)
      WHERE {
        ?university a coress-ont:University ;
                    coress-ont:atState ?state ;
                    coress-ont:hasCollege ?college .
        ?college coress-ont:hasDepartment ?department .
        ?department coress-ont:hasAgent ?agent .
        ?agent coress-ont:performsRole ?authorRole .
        ?authorRole a coress-ont:Author ;
                    coress-ont:submits ?publication .
      }
      GROUP BY ?state ?university
    }
    GROUP BY ?state
  }
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?publicationCount)
    WHERE {
      ?university a coress-ont:University ;
                  coress-ont:atState ?state ;
                  coress-ont:hasCollege ?college .
      ?college coress-ont:hasDepartment ?department .
      ?department coress-ont:hasAgent ?agent .
      ?agent coress-ont:performsRole ?authorRole .
      ?authorRole a coress-ont:Author ;
                  coress-ont:submits ?publication .
    }
    GROUP BY ?state ?university
  }
  FILTER(?publicationCount = ?maxPublicationCount)
}
ORDER BY ?state

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?state ?university ?publicationCount
WHERE {
  {
    SELECT ?state (MAX(?p_count) AS ?maxPublicationCount)
    WHERE {
      {
        SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?p_count)
        WHERE {
          ?publication coress-ont:submittedBy ?author .
          ?author a coress-ont:Author ;
                  coress-ont:isPerformedBy ?agent .
          ?agent coress-ont:worksInDepartment ?department .
          ?department coress-ont:departmentOf ?college .
          ?college coress-ont:collegeOf ?university .
          ?university coress-ont:atState ?state .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?publicationCount)
    WHERE {
      ?publication coress-ont:submittedBy ?author .
      ?author a coress-ont:Author ;
              coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?department .
      ?department coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  FILTER (?publicationCount = ?maxPublicationCount)
}
ORDER BY ?state ?university

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (COUNT(?agent) AS ?missingCount)
WHERE {
  ?agent a coress-ont:Agent ;
         coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName . }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)
LIMIT 1

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "storm") ||
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "hurricane") ||
    CONTAINS(LCASE(STR(?attribute)), "tornado") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "tornado")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?department
WHERE {
  ?department a coress-ont:Department .
}

