PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricaneEvent ?hazardAttribute ?attributeValue ?place ?damageType ?damageValue ?damageTime
WHERE {
  ?hurricaneEvent a ?eventType .
  VALUES ?eventType {
    kwg-ont:NOAAHurricane
    kwg-ont:NOAAMarineHurricaneTyphoon
    kwg-ont:NOAATropicalStorm
    kwg-ont:NOAAMarineTropicalStorm
  }

  OPTIONAL {
    ?noaaHazard kwg-ont:hasPart ?hurricaneEvent ;
                kwg-ont:hasStormTrack/kwg-ont:hasStormTracklet ?tracklet .
    ?tracklet kwg-ont:spatialRelation ?place .
    ?place a/rdfs:subClassOf* kwg-ont:AdministrativeRegion .
    {
      ?trackletObsCollection sosa:hasFeatureOfInterest ?tracklet ;
                             sosa:hasMember ?trackletObs .
      ?trackletObs sosa:observedProperty ?hazardAttribute ;
                   sosa:hasSimpleResult ?attributeValue .
      ?hazardAttribute a kwg-ont:StormTrackletObservableProperty .
    }
    UNION
    {
      ?magCollection sosa:hasFeatureOfInterest ?hurricaneEvent ;
                     a kwg-ont:MagnitudeObservationCollection ;
                     sosa:hasMember ?magObs .
      ?magObs sosa:observedProperty ?hazardAttribute ;
              sosa:hasSimpleResult ?attributeValue .
    }
  }

  OPTIONAL {
    ?impactCollection sosa:hasFeatureOfInterest ?hurricaneEvent ;
                      a kwg-ont:ImpactObservationCollection ;
                      sosa:hasMember ?damageObs .
    ?damageObs sosa:observedProperty ?damageType ;
               sosa:hasSimpleResult ?damageValue .
    OPTIONAL {
      ?impactCollection sosa:phenomenonTime ?timeEntity .
      { ?timeEntity time:inXSDDateTime ?damageTime . }
      UNION
      { ?timeEntity time:inXSDDate ?damageTime . }
      UNION
      { ?timeEntity time:hasBeginning/time:inXSDDateTime ?damageTime . }
    }
  }
  FILTER(BOUND(?hazardAttribute) || BOUND(?damageType))
}
ORDER BY ?hurricaneEvent

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT
    ?hazardEvent
    ?name
    ?startDate
    ?endDate
    ?affectedArea
    ?cropDamage
    ?infraDamage
    ?deaths
WHERE {
    ?hazardEvent rdf:type kwgl-ont:HazardEvent .

    OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name . }
    OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
    OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
    OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea . }
    OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }
    OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
    OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }
}
ORDER BY ?hazardEvent

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?university ?publicationCount
WHERE {
  {
    SELECT ?state (MAX(?pCount) AS ?maxPublicationCount)
    WHERE {
      SELECT ?state ?university (COUNT(DISTINCT ?publication) as ?pCount)
      WHERE {
        ?university a coresr-ont:University ;
                    coresr-ont:locatedAt ?location .
        ?location coresr-ont:atState ?state .
        ?college coresr-ont:partOf ?university .
        ?department coresr-ont:partOf ?college .
        ?agent coresr-ont:associatedWith ?department .
        ?contributorRole coresr-ont:isPerformedBy ?agent .
        ?publication coresr-ont:hasContributor ?contributorRole .
      }
      GROUP BY ?state ?university
    }
    GROUP BY ?state
  }
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) as ?publicationCount)
    WHERE {
      ?university a coresr-ont:University ;
                  coresr-ont:locatedAt ?location .
      ?location coresr-ont:atState ?state .
      ?college coresr-ont:partOf ?university .
      ?department coresr-ont:partOf ?college .
      ?agent coresr-ont:associatedWith ?department .
      ?contributorRole coresr-ont:isPerformedBy ?agent .
      ?publication coresr-ont:hasContributor ?contributorRole .
    }
    GROUP BY ?state ?university
  }
  FILTER(?publicationCount = ?maxPublicationCount)
}
ORDER BY ?state

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?publication
WHERE {
  {
    ?role coresr-ont:contributedTo ?publication .
  }
  UNION
  {
    ?publication coresr-ont:submittedBy ?role .
  }
  ?agent coresr-ont:performsRole ?role .
  ?agent coresr-ont:associatedWith ?department .
}
GROUP BY ?publication
HAVING(COUNT(DISTINCT ?department) > 1)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?damageProperty ?propertyLabel ?domain ?range
WHERE {
  ?damageProperty a owl:DatatypeProperty .
  OPTIONAL { ?damageProperty rdfs:label ?propertyLabel . }
  OPTIONAL { ?damageProperty rdfs:domain ?domain . }
  OPTIONAL { ?damageProperty rdfs:range ?range . }

  FILTER (
    CONTAINS(LCASE(STR(?damageProperty)), "damage") ||
    CONTAINS(LCASE(?propertyLabel), "damage")
  )
}
ORDER BY ?damageProperty

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT (GROUP_CONCAT(DISTINCT ?attr_str; SEPARATOR=", ") AS ?attributes) (COUNT(DISTINCT ?attribute) AS ?attributeCount)
WHERE {
  {
    ?place a kwgl-ont:Place .
    ?place ?attribute ?value .
    FILTER(CONTAINS(LCASE(STR(?attribute)), "tornadoes"))
  }
  UNION
  {
    ?tornado a kwgl-ont:Tornado .
    ?tornado ?attribute ?value .
  }
  BIND(STR(?attribute) AS ?attr_str)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?authorName ?field (GROUP_CONCAT(DISTINCT ?publication; SEPARATOR=", ") AS ?publications)
WHERE {
    ?authorRole a coress-ont:Author ;
                coress-ont:submits ?publication ;
                coress-ont:isPerformedBy ?agent .
    FILTER EXISTS { ?authorRole coress-ont:advisedBy ?advisor . }
    ?publication coress-ont:associatedFieldOfStudy ?field .
    ?agent coress-ont:hasFirstName ?firstName ;
           coress-ont:hasFamilyName ?familyName .
    BIND(CONCAT(?firstName, " ", ?familyName) AS ?authorName)
}
GROUP BY ?authorName ?field
ORDER BY ?authorName ?field

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?department
WHERE {
  ?department rdf:type coresr-ont:Department .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?damageProperty ?label ?domain ?range
WHERE {
  ?damageProperty rdf:type owl:DatatypeProperty .

  OPTIONAL { ?damageProperty rdfs:label ?label . }
  OPTIONAL { ?damageProperty rdfs:domain ?domain . }
  OPTIONAL { ?damageProperty rdfs:range ?range . }

  FILTER (
    CONTAINS(LCASE(STR(?damageProperty)), "damage") ||
    CONTAINS(LCASE(?label), "damage")
  )

  { ?damageProperty rdfs:domain kwgl-ont:HazardEvent . }
  UNION
  { ?damageProperty rdfs:domain kwgl-ont:Place . }
}
ORDER BY ?damageProperty

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?placeName ?healthAttribute ?value
WHERE {
  VALUES ?healthAttribute {
    kwgl-ont:percentDiabetic
    kwgl-ont:percentObese
    kwgl-ont:percentBelowPovertyLine
  }
  ?place ?healthAttribute ?value .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?publication ?submissionDate
WHERE {
  ?publication rdf:type coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricane ?hazardAttribute ?place ?impactDetail ?impactValue ?impactTime
WHERE {
  ?hurricane a kwg-ont:NOAAHurricane .
  ?hurricane geo:hasGeometry ?place .

  OPTIONAL {
    ?magnitudeObs a kwg-ont:MagnitudeObservation ;
                  sosa:hasFeatureOfInterest ?hurricane ;
                  sosa:observedProperty ?hazardAttribute .
  }

  OPTIONAL {
    ?impactObs a kwg-ont:ImpactObservation ;
               sosa:hasFeatureOfInterest ?hurricane ;
               sosa:observedProperty ?impactDetail ;
               sosa:hasSimpleResult ?impactValue .
    OPTIONAL {
      ?impactObs sosa:phenomenonTime ?impactTime .
    }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?attribute ?count
WHERE {
  {
    SELECT (COUNT(DISTINCT ?attr) AS ?count)
    WHERE {
      ?attr a owl:DatatypeProperty .
      ?attr rdfs:domain kwgl-ont:Place .
      OPTIONAL { ?attr rdfs:label ?label . }
      FILTER (
        CONTAINS(LCASE(STR(?attr)), "tornado") ||
        CONTAINS(LCASE(?label), "tornado")
      )
    }
  }
  {
    SELECT DISTINCT ?attribute
    WHERE {
      ?attribute a owl:DatatypeProperty .
      ?attribute rdfs:domain kwgl-ont:Place .
      OPTIONAL { ?attribute rdfs:label ?label . }
      FILTER (
        CONTAINS(LCASE(STR(?attribute)), "tornado") ||
        CONTAINS(LCASE(?label), "tornado")
      )
    }
  }
}
ORDER BY ?attribute

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiValue
WHERE {
  ?publication coresr-ont:hasIdentifier ?doi .
  ?doi coresr-ont:doiAsString ?doiValue .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?climateAttribute
WHERE {
    ?collection a kwg-ont:ClimateDivisionObservationCollection ;
                sosa:hasFeatureOfInterest ?place ;
                sosa:hasMember ?propCollection .
    ?place a kwg-ont:USClimateDivision .
    ?propCollection sosa:observedProperty ?climateAttribute .
    ?climateAttribute a kwg-ont:ClimateObservableProperty .
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?place ?name
WHERE {
  ?place a geo:SpatialObject .
  FILTER NOT EXISTS { ?place a geo:Geometry . }
  OPTIONAL {
    ?place kwg-ont:hasName | kwg-ont:hasDisasterName | kwg-ont:hasFireName | kwg-ont:hasIncidentName | kwg-ont:hospitalName | kwg-ont:pharmacyName | kwg-ont:publicHealthDepartmentName | kwg-ont:siteName | kwg-ont:climateDivisionName | kwg-ont:cbsaName | kwg-ont:hasRoadName ?name .
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?typeName (AVG(days-from-duration(?publicationDate - ?submissionDate)) AS ?avgDurationInDays)
WHERE {
  ?publication coresr-ont:hasPublicationType ?pubType ;
               coresr-ont:dateOfSubmission ?submissionDate ;
               coresr-ont:dateOfPublication ?publicationDate .
  ?pubType coresr-ont:typeAsString ?typeName .
}
GROUP BY ?typeName
ORDER BY DESC(?avgDurationInDays)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?title ?submissionDate
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasTitle ?title ;
               coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?state ?university ?pubCount
WHERE {
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?pubCount)
    WHERE {
      ?publication coresr-ont:submittedBy ?authorRole .
      ?agent coresr-ont:performsRole ?authorRole .
      ?agent coresr-ont:associatedWith ?department .
      ?department coresr-ont:partOf ?college .
      ?college coresr-ont:partOf ?university .
      ?university coresr-ont:locatedAt ?location .
      ?location coresr-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  {
    SELECT ?state (MAX(?pCount) AS ?maxPubCount)
    WHERE {
      {
        SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?pCount)
        WHERE {
          ?publication coresr-ont:submittedBy ?authorRole .
          ?agent coresr-ont:performsRole ?authorRole .
          ?agent coresr-ont:associatedWith ?department .
          ?department coresr-ont:partOf ?college .
          ?college coresr-ont:partOf ?university .
          ?university coresr-ont:locatedAt ?location .
          ?location coresr-ont:atState ?state .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  FILTER(?pubCount = ?maxPubCount)
}
ORDER BY ?state ?university

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?geographicalPlace ?attribute ?attributeLabel ?value ?geometry
WHERE {
  # A flood hazard event is treated as the geographical place of interest
  ?geographicalPlace a ?floodType .
  VALUES ?floodType {
    kwg-ont:NOAAFlood
    kwg-ont:NOAAFlashFlood
    kwg-ont:NOAACoastalFlood
    kwg-ont:NOAALakeshoreFlood
  }

  # Find observations (attributes and details) made about this flood event
  ?observation sosa:hasFeatureOfInterest ?geographicalPlace ;
               sosa:observedProperty ?attribute ;
               sosa:hasSimpleResult ?value .

  # Optionally get the human-readable label for the attribute
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  # Optionally get the geometry of the geographical place
  OPTIONAL {
    { ?geographicalPlace kwg-ont:hasSegment/(kwg-ont:startsFrom|kwg-ont:endsAt)/kwg-ont:hasGeometry ?geometry . }
    UNION
    { ?geographicalPlace geo:hasDefaultGeometry ?geometry . }
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?department
WHERE {
  ?department rdf:type coresr-ont:Department .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "earthquake") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "earthquake")
  )
}
ORDER BY ?attribute

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?place ?attribute ?value ?startDate ?endDate
WHERE {
    ?hurricane a kwgl-ont:Hurricane ;
               kwgl-ont:hasImpacted ?place .

    {
        # Get hurricane-specific hazard attributes
        ?hurricane ?attribute ?value .
        VALUES ?attribute {
            kwgl-ont:hasName
            kwgl-ont:affectedAreaInAcres
            kwgl-ont:damageToCropsInDollars
            kwgl-ont:damageToInfrastructureInDollars
            kwgl-ont:numberOfDeaths
        }
    }
    UNION
    {
        # Get damage impact details from the place
        ?place ?attribute ?value .
        { ?attribute rdfs:subPropertyOf* kwgl-ont:dollarDamageOfHurricanesImpactingPlace . }
        UNION
        { ?attribute rdfs:subPropertyOf* kwgl-ont:numberOfHurricanesImpactingPlace . }
    }

    # Optionally get the temporal data for the hurricane event
    OPTIONAL { ?hurricane kwgl-ont:hasStartDate ?startDate . }
    OPTIONAL { ?hurricane kwgl-ont:hasEndDate ?endDate . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?city ?university ?college
WHERE {
  ?university a coress-ont:University ;
              coress-ont:atCity ?city ;
              coress-ont:hasCollege ?college .
}
ORDER BY ?city ?university ?college

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?author ?advisor
WHERE {
  ?author_role rdf:type coresr-ont:Author ;
               coresr-ont:isPerformedBy ?author ;
               coresr-ont:advisedBy ?advisor_role .

  ?advisor_role rdf:type coresr-ont:Advisor ;
                coresr-ont:isPerformedBy ?advisor .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?damageType ?damageDetail
WHERE {
  ?impactObs a kwg-ont:ImpactObservation ;
             sosa:hasFeatureOfInterest ?hazard ;
             sosa:observedProperty ?damageType ;
             sosa:hasSimpleResult ?damageDetail .
  ?hazard a kwg-ont:Hazard .
  ?damageType rdfs:subClassOf* kwg-ont:ImpactObservableProperty .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?placeName ?population ?households ?poverty ?diabetic ?obese
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?poverty . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic . }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT DISTINCT ?author
WHERE {
  ?author coress-ont:performsRole ?role .
  ?role a coress-ont:Author .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "diabetic") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "diabetic") ||
    CONTAINS(LCASE(STR(?attribute)), "obese") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "obese")
  )
}
ORDER BY ?attribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?name
WHERE {
  { ?place kwg-ont:hospitalName ?name . }
  UNION
  { ?place kwg-ont:pharmacyName ?name . }
  UNION
  { ?place kwg-ont:publicHealthDepartmentName ?name . }
  UNION
  { ?place kwg-ont:siteName ?name . }
  UNION
  { ?place kwg-ont:cbsaName ?name . }
  UNION
  { ?place kwg-ont:hasDisasterName ?name . }
  UNION
  { ?place kwg-ont:hasIncidentName ?name . }
  UNION
  { ?place kwg-ont:hasFireName ?name . }
  UNION
  { ?place kwg-ont:hasRoadName ?name . }
  UNION
  { ?place kwg-ont:climateDivisionName ?name . }
  UNION
  { ?place kwg-ont:hasName ?name . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT (GROUP_CONCAT(DISTINCT STR(?hazard); SEPARATOR=", ") AS ?earthquakeHazards) (COUNT(DISTINCT ?hazard) AS ?count)
WHERE {
  { ?hazard rdf:type kwgl-ont:Earthquake . }
  UNION
  { ?hazard kwgl-ont:hasHazardType kwglr:earthquake . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?city ?university ?college
WHERE {
  ?university coress-ont:atCity ?city .
  ?college coress-ont:collegeOf ?university .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?contactInfo .
    ?contactInfo a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?type (AVG(?timeDiffInDays) AS ?averageDays)
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate ;
               coresr-ont:dateOfPublication ?publicationDate ;
               coresr-ont:hasPublicationType ?pubType .

  ?pubType coresr-ont:typeAsString ?type .

  BIND( (?publicationDate - ?submissionDate) / xsd:dayTimeDuration("P1D") AS ?timeDiffInDays )
}
GROUP BY ?type
ORDER BY DESC(?averageDays)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazardEvent
  ?hazardName
  ?hazardType
  ?startDate
  ?endDate
  ?numberOfDeaths
  ?damageToCrops
  ?damageToInfrastructure
  ?affectedArea
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea . }
}
ORDER BY DESC(?startDate) ?hazardName

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?placeType ?healthConcernOrAttribute
WHERE {
  {
    # Public health observable properties are linked to Administrative Regions via PublicHealthObservationCollection
    BIND(kwg-ont:AdministrativeRegion AS ?placeType)
    ?healthConcernOrAttribute rdfs:subClassOf kwg-ont:PublicHealthObservableProperty .
    FILTER(?healthConcernOrAttribute != kwg-ont:PublicHealthObservableProperty)
  }
  UNION
  {
    # Air pollutants are measured at Air Quality Sites
    BIND(kwg-ont:AirQualitySite AS ?placeType)
    ?healthConcernOrAttribute rdfs:subClassOf kwg-ont:AirPollutant .
    FILTER(?healthConcernOrAttribute != kwg-ont:AirPollutant)
  }
  UNION
  {
    # Hospitals are geographical features with specific health-related attributes
    BIND(kwg-ont:Hospital AS ?placeType)
    VALUES ?healthConcernOrAttribute {
      kwg-ont:hospitalType
      kwg-ont:traumaCareLevel
      kwg-ont:noHospitalBeds
      kwg-ont:hospitalStatus
      kwg-ont:helipadAvailability
    }
  }
}
ORDER BY ?placeType ?healthConcernOrAttribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "earthquake") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "earthquake")
  )
}
ORDER BY ?attribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?detail_property ?detail_value ?time
WHERE {
  ?hazard a kwg-ont:Hazard .

  ?hazard ?detail_property ?detail_value .
  FILTER(isLiteral(?detail_value))

  OPTIONAL {
    { ?hazard kwg-ont:hasTemporalScope/time:inXSDDateTime ?time . }
    UNION
    { ?collection sosa:hasFeatureOfInterest ?hazard ;
                  sosa:phenomenonTime/time:inXSDDateTime ?time . }
    UNION
    { ?hazard kwg-ont:hasDeclaration/kwg-ont:hasDeclarationDate/time:inXSDDateTime ?time . }
    UNION
    {
      ?collection sosa:hasFeatureOfInterest ?hazard ;
                  sosa:hasMember/sosa:hasSimpleResult ?time_val .
      FILTER(datatype(?time_val) = xsd:dateTime)
      BIND(?time_val AS ?time)
    }
  }
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a/rdfs:subClassOf* geo:SpatialObject .
  FILTER NOT EXISTS { ?place a/rdfs:subClassOf* geo:Geometry . }
  ?place (kwg-ont:hasName | kwg-ont:cbsaName | kwg-ont:climateDivisionName | kwg-ont:hasDisasterName | kwg-ont:hasFireName | kwg-ont:hasIncidentName | kwg-ont:hasRoadName | kwg-ont:hospitalName | kwg-ont:pharmacyName | kwg-ont:publicHealthDepartmentName | kwg-ont:siteName | rdfs:label) ?name .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?city ?university ?college
WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .
  ?location coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
  ?college a coresr-ont:College ;
           coresr-ont:partOf ?university .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?fieldOfStudy ?publicationTitle
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:associatedFieldOfStudy ?fieldOfStudy ;
               coress-ont:hasTitle ?publicationTitle .
