                 sosa:hasFeatureOfInterest ?place;
                 sosa:hasMember ?observation.

  ?observation sosa:observedProperty ?attribute;
               sosa:hasSimpleResult ?value.

  ?attribute a kwg-ont:CensusObservableProperty;
             rdfs:label ?attributeLabel.
}
ORDER BY ?placeLabel ?attributeLabel

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
