  ?obsCollection sosa:hasMember ?observation .
  ?observation a kwg-ont:CensusACS5YearEstimatesObservation ;
               sosa:observedProperty ?demographicAttribute ;
               sosa:hasSimpleResult ?value .
  ?demographicAttribute rdfs:subClassOf* kwg-ont:CensusObservableProperty .
}

