PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?state ?university ?pubCount
WHERE {
  # Subquery to calculate the max publication count for each state
  {
    SELECT ?state (MAX(?count) AS ?maxPubCount)
    WHERE {
      # Inner subquery to count publications for each university
      {
        SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?count)
        WHERE {
          ?university rdf:type coresr-ont:University ;
                      coresr-ont:locatedAt/coresr-ont:atState ?state .
          ?college coresr-ont:partOf ?university .
          ?department coresr-ont:partOf ?college .
          ?agent coresr-ont:associatedWith ?department .
          ?author coresr-ont:isPerformedBy ?agent ;
                  rdf:type coresr-ont:Author .
          ?publication coresr-ont:submittedBy ?author .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }

  # Recalculate counts to find the specific university matching the max count
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?pubCount)
    WHERE {
      ?university rdf:type coresr-ont:University ;
                  coresr-ont:locatedAt/coresr-ont:atState ?state .
      ?college coresr-ont:partOf ?university .
      ?department coresr-ont:partOf ?college .
      ?agent coresr-ont:associatedWith ?department .
      ?author coresr-ont:isPerformedBy ?agent ;
              rdf:type coresr-ont:Author .
      ?publication coresr-ont:submittedBy ?author .
    }
    GROUP BY ?state ?university
  }

  # Filter to join the two results
  FILTER (?pubCount = ?maxPubCount)
}
ORDER BY ?state ?university

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department ?missingCount
WHERE {
    {
        SELECT ?department (COUNT(?agent) AS ?missingCount)
        WHERE {
            ?department a coresr-ont:Department .
            ?department coresr-ont:hasAssociatedAgent ?agent .
            MINUS {
                ?agent coresr-ont:hasContactInformation ?contact .
                ?contact a coresr-ont:FamilyName .
            }
        }
        GROUP BY ?department
    }
    FILTER NOT EXISTS {
        {
            SELECT (COUNT(?other_agent) AS ?otherMissingCount)
            WHERE {
                ?other_department a coresr-ont:Department .
                ?other_department coresr-ont:hasAssociatedAgent ?other_agent .
                 MINUS {
                    ?other_agent coresr-ont:hasContactInformation ?other_contact .
                    ?other_contact a coresr-ont:FamilyName .
                }
            }
            GROUP BY ?other_department
        }
        FILTER(?otherMissingCount > ?missingCount)
    }
}

