SELECT ?publication
WHERE {
    {
        ?role coresr-ont:contributedTo ?publication .
        ?role a coresr-ont:Contributor .
        ?agent coresr-ont:performsRole ?role .
    }
    UNION
    {
        ?publication coresr-ont:submittedBy ?role .
        ?role a coresr-ont:Author .
        ?agent coresr-ont:performsRole ?role .
    }
    ?agent coresr-ont:associatedWith ?department .
}
GROUP BY ?publication
HAVING (COUNT(DISTINCT ?department) > 1)

