                     sosa:hasSimpleResult ?impactValue.
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?geographicalPlace ?floodHazard ?attribute ?value
WHERE {
  VALUES ?floodType {
    kwg-ont:NOAAFlood
    kwg-ont:NOAAFlashFlood
    kwg-ont:NOAACoastalFlood
    kwg-ont:NOAALakeshoreFlood
  }
  ?floodHazard a ?floodType .
  ?floodHazard kwg-ont:spatialRelation ?geographicalPlace .

  ?observation sosa:hasFeatureOfInterest ?floodHazard ;
               sosa:observedProperty ?attribute ;
               sosa:hasSimpleResult ?value .
}
ORDER BY ?geographicalPlace ?floodHazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?placeName ?floodHazard ?attribute ?value
WHERE {
  ?place a kwg-ont:AdministrativeRegion ;
         rdfs:label ?placeName .

  ?floodHazard kwg-ont:spatialRelation ?place .

  VALUES ?floodType {
    kwg-ont:NOAAFlood
    kwg-ont:NOAAFlashFlood
    kwg-ont:NOAACoastalFlood
    kwg-ont:NOAALakeshoreFlood
  }
  ?floodHazard a ?floodType .

  {
    ?floodHazard ?attribute ?value .
    FILTER(isLiteral(?value))
  }
  UNION
  {
    ?obsCollection sosa:hasFeatureOfInterest ?floodHazard ;
                   sosa:hasMember ?observation .
    ?observation sosa:observedProperty ?attribute ;
                 sosa:hasSimpleResult ?value .
  }
  UNION
  {
    ?episode kwg-ont:episodeHasPart ?floodHazard ;
             kwg-ont:hasNarrative ?value .
    BIND(kwg-ont:hasNarrative AS ?attribute)
  }
}
ORDER BY ?placeName ?floodHazard

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?earthquakeHazard (COUNT(?earthquakeHazard) AS ?count)
WHERE {
