PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?placeName ?stormEvent ?stormName ?stormHazardType ?startDate ?endDate ?affectedArea ?cropDamage ?infraDamage ?deaths
WHERE {
  ?place a kwgl-ont:Place;
         kwgl-ont:hasName ?placeName.

  ?stormEvent kwgl-ont:hasImpacted ?place;
              kwgl-ont:hasHazardType ?stormHazardType.

  VALUES ?stormHazardType {
    kwglr:blizzard kwglr:dustStorm kwglr:iceStorm kwglr:marineHighWind
    kwglr:marineStrongWind kwglr:marineThunderstormWind kwglr:marineTropicalDepression
    kwglr:marineTropicalStorm kwglr:stormSurgeTide kwglr:strongWind
    kwglr:thunderstormWind kwglr:tornado kwglr:tropicalDepression
    kwglr:tropicalStorm kwglr:hurricane kwglr:winterStorm
  }

  OPTIONAL { ?stormEvent kwgl-ont:hasName ?stormName. }
  OPTIONAL { ?stormEvent kwgl-ont:hasStartDate ?startDate. }
  OPTIONAL { ?stormEvent kwgl-ont:hasEndDate ?endDate. }
  OPTIONAL { ?stormEvent kwgl-ont:affectedAreaInAcres ?affectedArea. }
  OPTIONAL { ?stormEvent kwgl-ont:damageToCropsInDollars ?cropDamage. }
  OPTIONAL { ?stormEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage. }
  OPTIONAL { ?stormEvent kwgl-ont:numberOfDeaths ?deaths. }
}

