PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?university ?city
WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .
  ?location coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS {
    ?agent coress-ont:hasFamilyName ?familyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)
LIMIT 1

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?hazard ?damageType ?damageValue
WHERE {
  ?impactObs a kwg-ont:ImpactObservation ;
             sosa:hasFeatureOfInterest ?hazard ;
             sosa:observedProperty ?damageType ;
             sosa:hasSimpleResult ?damageValue .
  ?hazard a kwg-ont:NOAAHazardEvent .
  ?damageType rdfs:subClassOf* kwg-ont:ImpactObservableProperty .
  FILTER ( CONTAINS(str(?damageType), "damage") )
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?cropDamage ?infrastructureDamage ?numberOfDeaths ?affectedArea
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL {
    ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage .
  }
  OPTIONAL {
    ?hazard kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage .
  }
  OPTIONAL {
    ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths .
  }
  OPTIONAL {
    ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea .
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasDOI ?doi .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardEvent ?impactPropertyLabel ?impactValue
WHERE {
  ?impactCollection a kwg-ont:ImpactObservationCollection ;
                    sosa:hasFeatureOfInterest ?hazardEvent ;
                    sosa:hasMember ?impactObservation .
  ?impactObservation sosa:observedProperty ?impactProperty ;
                     sosa:hasSimpleResult ?impactValue .
  ?impactProperty rdfs:label ?impactPropertyLabel .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?state ?university ?publicationCount
WHERE {
  {
    SELECT ?state (MAX(?count) as ?maxCount)
    WHERE {
      {
        SELECT ?state ?university (COUNT(DISTINCT ?publication) as ?count)
        WHERE {
          ?publication coress-ont:submittedBy ?author .
          ?author a coress-ont:Author .
          ?agent coress-ont:performsRole ?author .
          ?agent coress-ont:worksInDepartment ?department .
          ?department coress-ont:departmentOf ?college .
          ?college coress-ont:collegeOf ?university .
          ?university coress-ont:atState ?state .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) as ?publicationCount)
    WHERE {
      ?publication coress-ont:submittedBy ?author .
      ?author a coress-ont:Author .
      ?agent coress-ont:performsRole ?author .
      ?agent coress-ont:worksInDepartment ?department .
      ?department coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  FILTER (?publicationCount = ?maxCount)
}
ORDER BY ?state

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?placeName ?floodAttribute ?value
WHERE {
  VALUES ?baseFloodAttribute {
    kwgl-ont:dollarDamageOfFloodsImpactingPlace
    kwgl-ont:numberOfFloodsImpactingPlace
  }
  ?floodAttribute rdfs:subPropertyOf* ?baseFloodAttribute .
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName ;
         ?floodAttribute ?value .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?eventName ?placeName ?damageToCrops ?damageToInfrastructure ?deaths ?affectedArea
WHERE {
  ?hazardEvent kwgl-ont:hasHazardType kwglr:tornado ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:hasStartDate ?startDate ;
               kwgl-ont:hasEndDate ?endDate .

  FILTER (?startDate >= "2020-01-01"^^xsd:date && ?endDate <= "2020-12-31"^^xsd:date)

  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?eventName . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?earthquake ?hazardType ?name ?startDate ?endDate ?deaths ?cropDamage ?infraDamage ?area
WHERE {
  ?earthquake rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?earthquake kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?earthquake kwgl-ont:hasName ?name . }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?area . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT (GROUP_CONCAT(DISTINCT ?earthquakeHazard; separator=", ") AS ?earthquakeHazards) (COUNT(DISTINCT ?earthquakeHazard) AS ?count)
WHERE {
  ?earthquakeHazard rdf:type kwg-ont:Earthquake .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?tornado ?placeName ?startDate ?endDate ?cropDamage ?infraDamage ?deaths
WHERE {
  ?tornado a kwgl-ont:Tornado .
  ?tornado kwgl-ont:hasImpacted ?place .
  ?tornado kwgl-ont:hasStartDate ?startDate .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }
  OPTIONAL { ?tornado kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?tornado kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?tornado kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?tornado kwgl-ont:numberOfDeaths ?deaths . }

  FILTER (?startDate >= "2020-01-01"^^xsd:date && ?startDate <= "2021-12-31"^^xsd:date)
}
ORDER BY DESC(?startDate)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?hazardName ?hazardTypeLabel ?startDate ?endDate ?affectedArea ?cropDamage ?infraDamage ?deaths
WHERE {
  ?hazard a kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName . }
  OPTIONAL {
    ?hazard kwgl-ont:hasHazardType ?hazardType .
    ?hazardType rdfs:label ?hazardTypeLabel .
  }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?department
WHERE {
  ?department rdf:type coresr-ont:Department .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?placeName ?population ?households ?povertyPercentage ?diabeticPercentage ?obesePercentage
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyPercentage . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabeticPercentage . }
  OPTIONAL { ?place kwgl-ont:percentObese ?obesePercentage . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazardAttribute ?totalCount
WHERE {
  {
    SELECT DISTINCT ?hazardAttribute WHERE {
      ?place a kwgl-ont:Place .
      ?place ?hazardAttribute [] .
      FILTER(CONTAINS(LCASE(STR(?hazardAttribute)), "tornado"))
    }
  }
  {
    SELECT (COUNT(DISTINCT ?p) AS ?totalCount) WHERE {
      ?s a kwgl-ont:Place .
      ?s ?p [] .
      FILTER(CONTAINS(LCASE(STR(?p)), "tornado"))
    }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
  ?domain
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  FILTER (
    REGEX(STR(?attribute), "Damage|damage|Deaths|deaths|Affected|affected", "i") ||
    (REGEX(STR(?attribute), "numberOf") && ?attribute != kwgl-ont:hasNumberOfHouseHolds)
  )

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:domain ?domain . }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    FILTER(?parentAttribute != ?attribute)
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }
}
ORDER BY ?attribute
